    // RFC zorder-superposition D3b — sidecar substrate.zgrid (grille de tri)
    // -------------------------------------------------------------------

    /// Chantier 4 — préfetch centré : bornes respectées, no-op hors
    /// communauté, communautés sans range → Ok silencieux.
    #[test]
    fn prefetch_community_centered_bounds() {
        let (_td, s) = store();
        // Communauté 1 : 10 nœuds via le chemin store (ranges maintenues).
        let mut first = 0u32;
        for _ in 0..10u32 {
            let id = s.create_node_in_community(&["L"], 1);
            if first == 0 {
                first = id.0 as u32;
            }
        }
        s.flush().unwrap();
        let (lo, hi) = s.community_slot_range(1).expect("communauté 1");
        assert_eq!(first, lo);
        // Centre au milieu, rayon large → couvre toute la communauté.
        s.prefetch_community_centered(1, lo, u32::MAX).unwrap();
        // Rayon 0 → un seul slot.
        s.prefetch_community_centered(1, lo, 0).unwrap();
        // Centre hors communauté → no-op silencieux.
        s.prefetch_community_centered(1, hi + 100, 5).unwrap();
        // Communauté vide → no-op silencieux.
        s.prefetch_community_centered(99, 1, 5).unwrap();
        // Le préfetch ne mute rien.
        let before = s.window_query_2d(1, 0, u16::MAX, 0, u32::MAX).unwrap();
        assert_eq!(
            before.len(),
            10,
            "préfetche ne doit pas altérer les données"
        );
    }

    /// RFC §16.1 — équivalence ingestion zone-direct vs chemin unitaire :
    /// compteurs O(1), chaînes sortantes (first_edge_off/next_from) et
    /// entrantes (next_to) identiques.
    #[test]
    fn bulk_import_zone_direct_equivalence() {
        let labels: Vec<&str> = vec!["File", "Method", "File", "Class"];
        let edges: Vec<(u32, u32, &str)> = vec![
            (1, 2, "CALLS"),
            (2, 3, "CALLS"),
            (1, 3, "CALLS"),
            (3, 1, "IMPORTS"),
            (4, 2, "CALLS"),
            (2, 4, "CALLS"),
        ];

        // Chemin unitaire (sémantique de référence) via le trait
        // GraphStoreMut (compteurs labels/types maintenus).
        let (td, s_u) = store();
        let gm: &dyn obrain_core::graph::traits::GraphStoreMut = &s_u;
        let mut ids: Vec<NodeId> = Vec::new();
        for l in &labels {
            ids.push(gm.create_node(std::slice::from_ref(l)));
        }
        for &(a, b, ty) in &edges {
            gm.create_edge(ids[a as usize - 1], ids[b as usize - 1], ty);
        }
        s_u.flush().unwrap();

        // Chemin bulk zone-direct (store neuf).
        let td2 = tempfile::tempdir().unwrap();
        let s_b = SubstrateStore::create(td2.path().join("kb")).unwrap();
        s_b.bulk_import_labels_edges(&labels, &edges).unwrap();
        s_b.flush().unwrap();

        // Compteurs O(1) égaux.
        for l in ["File", "Method", "Class", "Nope"] {
            let (a, b) = (s_u.node_count_by_label(l), s_b.node_count_by_label(l));
            assert_eq!(a, b, "node_count_by_label({l}) unitaire vs bulk");
        }
        for ty in ["CALLS", "IMPORTS", "NOPE"] {
            assert_eq!(
                s_u.live_count_by_edge_type(ty),
                s_b.live_count_by_edge_type(ty),
                "live_count_by_edge_type({ty})"
            );
        }

        // Chaînes : collecte (dst,type) sortants par nœud via les listes.
        let type_name = |s: &SubstrateStore, id: u16| -> String {
            s.edge_types
                .read()
                .name_for(id)
                .map(|a| a.to_string())
                .unwrap_or_default()
        };
        let collect_out =
            |s: &SubstrateStore| -> std::collections::BTreeMap<u32, Vec<(u32, String)>> {
                let mut out = std::collections::BTreeMap::new();
                for node in 1..=4u32 {
                    let rec = s.writer().read_node(node).unwrap().unwrap();
                    let mut cur = rec.first_edge_off.to_u64() / EdgeRecord::SIZE as u64;
                    let mut v = Vec::new();
                    while cur != 0 {
                        let e = s.writer().read_edge(cur).unwrap().unwrap();
                        v.push((e.dst, type_name(s, e.edge_type)));
                        cur = e.next_from.to_u64() / EdgeRecord::SIZE as u64;
                    }
                    v.sort();
                    out.insert(node, v);
                }
                out
            };
        assert_eq!(collect_out(&s_u), collect_out(&s_b), "chaînes sortantes");

        // Chaînes entrantes : marcher next_to depuis la tête (plus grand id
        // du dst), reconstruite par scan simple des ids.
        let collect_in =
            |s: &SubstrateStore| -> std::collections::BTreeMap<u32, Vec<(u32, String)>> {
                let mut out = std::collections::BTreeMap::new();
                let m = s.next_edge_id.load(Ordering::Acquire);
                // tête par dst = plus grand id d'arête avec ce dst.
                let mut head: std::collections::HashMap<u32, u64> =
                    std::collections::HashMap::new();
                for id in 1..m {
                    if let Ok(Some(e)) = s.writer().read_edge(id) {
                        head.insert(e.dst, id);
                    }
                }
                for dst in 1..=4u32 {
                    let mut v = Vec::new();
                    if let Some(&hid) = head.get(&dst) {
                        let mut cur = hid;
                        while cur != 0 {
                            let e = s.writer().read_edge(cur).unwrap().unwrap();
                            v.push((e.src, type_name(s, e.edge_type)));
                            cur = e.next_to.to_u64() / EdgeRecord::SIZE as u64;
                        }
                    }
                    v.sort();
                    out.insert(dst, v);
                }
                out
            };
        assert_eq!(collect_in(&s_u), collect_in(&s_b), "chaînes entrantes");
        let _ = td2;
    }

    #[test]
    fn zgrid_absent_returns_none() {
        let (td, s) = store();
        let sub = s.writer().substrate();
        let sub = sub.lock();
        assert_eq!(
            sub.read_zgrid(),
            None,
            "store neuf : pas de grille persistée"
        );
        assert!(!td.path().join("kb").join(crate::file::zone::ZGRID).exists());
    }

    #[test]
    fn zgrid_roundtrip() {
        let (_td, s) = store();
        let sub = s.writer().substrate();
        {
            let sub = sub.lock();
            sub.write_zgrid(4, 32).unwrap();
        }
        let sub = sub.lock();
        assert_eq!(
            sub.read_zgrid(),
            Some((4, 32)),
            "roundtrip order/max_degree"
        );
    }

    #[test]
    fn zgrid_survives_reopen() {
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb");
        {
            let s = SubstrateStore::create(&path).unwrap();
            let sub = s.writer().substrate();
            let sub = sub.lock();
            sub.write_zgrid(6, 4096).unwrap();
        }
        // Réouverture (même en lecture seule) : la grille doit être lisible.
        let s = SubstrateStore::open(&path).unwrap();
        let sub = s.writer().substrate();
        let sub = sub.lock();
        assert_eq!(
            sub.read_zgrid(),
            Some((6, 4096)),
            "grille persistée lisible au reopen"
        );
    }

    // -------------------------------------------------------------------
    // RFC zorder-superposition D3b — voie accélérée zruns
    // -------------------------------------------------------------------

    /// SÉLECTEUR ADAPTATIF — résultat IDENTIQUE quelle que soit la sélection
    /// (scan vs zruns) : communauté ≥ seuil (zruns réellement actif) → les
    /// deux voies rendent exactement les mêmes résultats sur des fenêtres
    /// variées (le régime scan des petites communautés est couvert par les
    /// tests exact==sorted existants).
    #[test]
    fn selecteur_adaptatif_resultats_identiques_quel_que_soit_le_chemin() {
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb-adapt");
        {
            let s = SubstrateStore::create(&path).unwrap();
            let mut updates = Vec::new();
            let mut ids: Vec<u64> = Vec::new();
            let mut st: u64 = 42;
            let mut rnd = move || {
                st ^= st << 13;
                st ^= st >> 7;
                st ^= st << 17;
                st
            };
            for _ in 0..700u32 {
                let id = s.create_node_in_community(&["L"], 1);
                ids.push(id.0);
                let v = ((rnd() % 65_535) as f32) / u16::MAX as f32;
                updates.push((id, v));
            }
            s.update_centrality_batch_f32(updates).unwrap();
            for _ in 0..400usize {
                let a = ids[(rnd() % ids.len() as u64) as usize];
                let b = ids[(rnd() % ids.len() as u64) as usize];
                if a != b {
                    let _ = s.create_synapse_slot(NodeId(a), NodeId(b), 0.9);
                }
            }
            s.flush().unwrap();
        }
        let deg_file = path.join(crate::degree_column::DEGREE_COLUMN_FILENAME);
        if deg_file.exists() {
            std::fs::remove_file(&deg_file).unwrap();
        }
        let s = SubstrateStore::open(&path).unwrap();
        s.repermuter_par_hilbert(4, 128).unwrap();
        let (first, last) = s.community_slot_range(1).unwrap();
        assert!(
            last - first + 1 >= 512,
            "communauté assez grande pour zruns"
        );
        assert!(
            s.community_zrows(1, first, last).unwrap().is_some(),
            "zruns actif"
        );
        let windows = [
            (0u16, u16::MAX, 0u32, u32::MAX),
            (0u16, u16::MAX, 1u32, 1u32),
            (0u16, u16::MAX, 5u32, u32::MAX),
            (30_000u16, 40_000u16, 3u32, 20u32),
            (0u16, 0u16, 0u32, u32::MAX),
            (u16::MAX, u16::MAX, 999u32, u32::MAX),
        ];
        for &(cl, ch, dl, dh) in &windows {
            let scan = s.window_query_2d(1, cl, ch, dl, dh).unwrap();
            let chemin = s.window_query_2d_sorted(1, cl, ch, dl, dh).unwrap();
            assert_eq!(scan, chemin, "zruns != scan c=[{cl},{ch}] d=[{dl},{dh}]");
        }
    }

    /// PROPRIÉTÉ (chantier 2) : sur un graphe aléatoire trié (zruns actif),
    /// `window_query_2d` ET `window_query_2d_sorted` doivent rendre
    /// EXACTEMENT l'oracle indépendant (filtre degré × centralité lu par
    /// slot) pour des centaines de requêtes aléatoires.
    #[test]
    fn window_2d_property_oracle_aleatoire() {
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb-prop");
        {
            let s = SubstrateStore::create(&path).unwrap();
            let mut updates = Vec::new();
            let mut ids: Vec<u64> = Vec::new();
            let mut st: u64 = 0xC0FF_EE00_1234_5678;
            let mut rnd = move || {
                st ^= st << 13;
                st ^= st >> 7;
                st ^= st << 17;
                st
            };
            for _ in 0..70u32 {
                let id = s.create_node_in_community(&["L"], 1);
                ids.push(id.0);
                let v = ((rnd() % 65_535) as f32) / u16::MAX as f32;
                updates.push((id, v));
            }
            s.update_centrality_batch_f32(updates).unwrap();
            for _ in 0..90usize {
                let a = ids[(rnd() % ids.len() as u64) as usize];
                let b = ids[(rnd() % ids.len() as u64) as usize];
                if a != b {
                    let _ = s.create_synapse_slot(NodeId(a), NodeId(b), 0.9);
                }
            }
            s.flush().unwrap();
        }
        // Re-hydratation degrés puis tri bulk → voie accélérée disponible.
        let deg_file = path.join(crate::degree_column::DEGREE_COLUMN_FILENAME);
        if deg_file.exists() {
            std::fs::remove_file(&deg_file).unwrap();
        }
        let s = SubstrateStore::open(&path).unwrap();
        s.repermuter_par_hilbert(4, 128).unwrap();
        let (first, last) = s.community_slot_range(1).expect("communauté 1");
        assert!(
            s.community_zrows(1, first, last).unwrap().is_some(),
            "zruns actif après bulk sort"
        );
        // Oracle : (centralité q16, degré) de chaque slot vivant de la communauté.
        let live: std::collections::HashSet<u64> = s.node_ids().iter().map(|n| n.0).collect();
        let mut oracle: Vec<(u64, u16, u32)> = Vec::new();
        for slot in first..=last {
            if !live.contains(&u64::from(slot)) {
                continue;
            }
            let Some(rec) = s.writer().read_node(slot).unwrap() else {
                continue;
            };
            if rec.is_tombstoned() {
                continue;
            }
            oracle.push((
                u64::from(slot),
                rec.centrality_cached,
                s.out_degree(NodeId(u64::from(slot))),
            ));
        }
        let mut st2: u64 = 0xFEED_FACE_CAFE_0001;
        let mut rnd2 = move || {
            st2 ^= st2 << 13;
            st2 ^= st2 >> 7;
            st2 ^= st2 << 17;
            st2
        };
        for q in 0..250usize {
            let (mut a, mut b) = ((rnd2() % 65_536) as u16, (rnd2() % 65_536) as u16);
            if a > b {
                std::mem::swap(&mut a, &mut b);
            }
            let mut dl = (rnd2() % 130) as u32;
            let dh = dl + (rnd2() % 40) as u32;
            if q % 7 == 0 {
                dl = dl.saturating_add(1000);
            } // au-delà du max
            let mut attendu: Vec<u32> = oracle
                .iter()
                .filter(|(_, c, d)| *c >= a && *c <= b && *d >= dl && *d <= dh)
                .map(|(slot, _, _)| *slot as u32)
                .collect();
            attendu.sort_unstable();
            let fast = s.window_query_2d_sorted(1, a, b, dl, dh).unwrap();
            let scan = s.window_query_2d(1, a, b, dl, dh).unwrap();
            assert_eq!(fast, scan, "q{q}: zruns != scan c=[{a},{b}] d=[{dl},{dh}]");
            assert_eq!(
                attendu,
                scan,
                "q{q}: scan != oracle c=[{a},{b}] d=[{dl},{dh}] ({} slots)",
                oracle.len()
            );
        }
    }

    #[test]
    fn window_sorted_zruns_equals_scan_after_bulk_sort() {
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb");
        // Étape 1 : création + arêtes (synapse) puis flush — les arêtes sont
        // écrites AVANT la première hydratation de la colonne degrés.
        {
            let s = SubstrateStore::create(&path).unwrap();
            let mut updates = Vec::new();
            let mut ids: Vec<u64> = Vec::new();
            for j in 0..60u32 {
                let id = s.create_node_in_community(&["L"], 1);
                ids.push(id.0);
                updates.push((id, (j as f32 * 1000.0) / u16::MAX as f32));
            }
            s.update_centrality_batch_f32(updates).unwrap();
            for i in 0..59u32 {
                let a = ids[i as usize];
                let b = ids[(i + 1) as usize];
                s.create_synapse_slot(NodeId(a), NodeId(b), 0.9).unwrap();
            }
            s.flush().unwrap();
        }
        // Re-hydratation degrés (le sidecar a pu être créé vide avant les
        // arêtes) puis tri de bulk (pose HILBERT_SORTED + zgrid).
        let deg_file = path.join(crate::degree_column::DEGREE_COLUMN_FILENAME);
        if deg_file.exists() {
            std::fs::remove_file(&deg_file).unwrap();
        }
        let s = SubstrateStore::open(&path).unwrap();
        s.repermuter_par_hilbert(4, 32).unwrap();

        // La voie accélérée est réellement disponible.
        let (first, last) = s.community_slot_range(1).expect("communauté 1");
        assert!(
            s.community_zrows(1, first, last).unwrap().is_some(),
            "zruns doit être actif après bulk sort (flag + zgrid + zone)"
        );

        // Fenêtres : égalité EXACTE voie accélérée vs scan (valeurs courantes
        // — aucune mutation depuis le tri, le contrat est respecté).
        // Cas limites « filtres & bornes » : extrêmes 0/65535, saturation
        // degré au-delà de max_degree=32, fenêtres vides, bande fine.
        let windows = [
            (0u16, u16::MAX, 0u32, u32::MAX),
            (0u16, u16::MAX, 1u32, 1u32),
            (0u16, u16::MAX, 33u32, u32::MAX), // d_lo > max_degree (32) → rangée saturée
            (0u16, u16::MAX, 1000u32, u32::MAX),
            (0u16, 0u16, 0u32, u32::MAX), // centralité 0 seulement
            (65_535u16, 65_535u16, 0u32, u32::MAX), // au-delà du max présent (59000)
            (0u16, 65_535u16, 0u32, 0u32), // degré 0 (dernier nœud de la chaîne)
            (0u16, u16::MAX, u32::MAX, u32::MAX), // d_lo == d_hi == MAX → vide
            (29_000u16, 31_000u16, 1u32, 1u32), // bande centrale fine
            (5_000u16, 5_000u16, 1u32, 1u32), // cellule fine
        ];
        for &(c_lo, c_hi, d_lo, d_hi) in windows.iter() {
            let fast = s.window_query_2d_sorted(1, c_lo, c_hi, d_lo, d_hi).unwrap();
            let scan = s.window_query_2d(1, c_lo, c_hi, d_lo, d_hi).unwrap();
            assert_eq!(
                fast, scan,
                "zruns != scan pour c=[{c_lo},{c_hi}] d=[{d_lo},{d_hi}]"
            );
            // Trié par slot croissant.
            assert!(fast.windows(2).all(|w| w[0] < w[1]), "résultat non trié");
        }
        // Bornes vérifiées par oracle : centralité 0 → exactement le nœud j=0
        // (q16 = 0), quel que soit le slot post-tri ; fenêtre au-delà du max
        // présent → vide.
        let c0 = s.window_query_2d(1, 0, 0, 0, u32::MAX).unwrap();
        assert_eq!(c0.len(), 1, "un seul nœud de centralité 0");
        let rec = s.writer().read_node(c0[0]).unwrap().unwrap();
        assert_eq!(rec.centrality_cached, 0, "le slot retourné a bien q16 == 0");
        let over = s.window_query_2d(1, 60_000, u16::MAX, 0, u32::MAX).unwrap();
        assert!(
            over.is_empty(),
            "aucune centralité >= 60000 (max présent 59000)"
        );
    }

    #[test]
