    /// Chantier 3 — la voie « layout trié » exige l'ABSENCE de mutations de
    /// features depuis le dernier tri. Une mise à jour de centralité post-tri
    /// (flag HILBERT_SORTED toujours posé, zgrid présent) doit désactiver
    /// zruns : la colonne Zorder ne reflète plus les valeurs courantes.
    #[test]
    fn sorted_view_invalidated_by_feature_mutation() {
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb4");
        {
            let s = SubstrateStore::create(&path).unwrap();
            let mut updates = Vec::new();
            let mut ids: Vec<u64> = Vec::new();
            for j in 0..30u32 {
                let id = s.create_node_in_community(&["L"], 1);
                ids.push(id.0);
                updates.push((id, (j as f32 * 2000.0) / u16::MAX as f32));
            }
            s.update_centrality_batch_f32(updates).unwrap();
            s.flush().unwrap();
        }
        let s = SubstrateStore::open(&path).unwrap();
        s.repermuter_par_hilbert(4, 32).unwrap();
        let (first, last) = s.community_slot_range(1).expect("communauté 1");
        assert!(s.sorted_view_valid(), "juste après le tri : vue saine");
        assert!(
            s.community_zrows(1, first, last).unwrap().is_some(),
            "zruns actif sur vue saine"
        );
        // Mutation de centralité post-tri (flag RESTE posé).
        let id = NodeId(u64::from(first));
        s.update_centrality_batch_f32(vec![(id, 0.9)]).unwrap();
        assert!(
            !s.sorted_view_valid(),
            "une mutation de centralité casse la vue triée"
        );
        assert!(
            s.community_zrows(1, first, last).unwrap().is_none(),
            "zruns doit se replier sur scan après mutation de features"
        );
        // Le scan exact reste correct.
        let scan = s.window_query_2d(1, 0, u16::MAX, 0, u32::MAX).unwrap();
        assert!(!scan.is_empty());
        // Nouveau tri → vue saine à nouveau.
        s.repermuter_par_hilbert(4, 32).unwrap();
        assert!(s.sorted_view_valid(), "re-tri : vue saine restaurée");
    }

    #[test]
    fn zrows_cache_invalidated_on_allocation() {
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb3");
        // setup identique à window_sorted… : création + arêtes + reopen + tri
        {
            let s = SubstrateStore::create(&path).unwrap();
            let mut updates = Vec::new();
            let mut ids: Vec<u64> = Vec::new();
            for j in 0..30u32 {
                let id = s.create_node_in_community(&["L"], 1);
                ids.push(id.0);
                updates.push((id, (j as f32 * 2000.0) / u16::MAX as f32));
            }
            s.update_centrality_batch_f32(updates).unwrap();
            for i in 0..20u32 {
                s.create_synapse_slot(NodeId(ids[i as usize]), NodeId(ids[i as usize + 1]), 0.9)
                    .unwrap();
            }
            s.flush().unwrap();
        }
        let deg_file = path.join(crate::degree_column::DEGREE_COLUMN_FILENAME);
        if deg_file.exists() {
            std::fs::remove_file(&deg_file).unwrap();
        }
        let s = SubstrateStore::open(&path).unwrap();
        s.repermuter_par_hilbert(4, 32).unwrap();
        let gen0 = s.zrows_gen.load(Ordering::Acquire);
        // Remplit le cache EXPLICITEMENT : le sélecteur adaptatif (seuil
        // calibré 4500) renvoie désormais un scan direct pour une communauté
        // de 30 nœuds — il ne peuple plus le cache via window_query_2d_sorted.
        let (f0, l0) = s.community_slot_range(1).expect("communauté 1");
        let _ = s.community_zrows(1, f0, l0).unwrap();
        {
            let cache = s.zrows_cache.read();
            assert!(
                cache.get(&1).is_some(),
                "cache zruns peuplé après chargement zrows"
            );
        }
        // Allocation en ligne → invalidation (flag clear + gen bump).
        s.create_node_in_community(&["L"], 1);
        let gen1 = s.zrows_gen.load(Ordering::Acquire);
        assert!(gen1 > gen0, "gen doit avancer après allocation");
        let (first, last) = s.community_slot_range(1).expect("communauté 1");
        assert!(
            s.community_zrows(1, first, last).unwrap().is_none(),
            "layout invalidé : zruns inactif jusqu'au prochain tri"
        );
        // Le scan exact reste correct.
        let scan = s.window_query_2d(1, 0, u16::MAX, 0, u32::MAX).unwrap();
        assert!(!scan.is_empty());
    }

    #[test]
    fn properties_survive_reopen() {
        use obrain_core::graph::traits::GraphStore;
        use std::sync::Arc;

        // ── (2026-08-20) CE TEST EST UN LECTEUR DE `OBRAIN_PROPS_V2` ────────
        //
        // Il ne pose pas le drapeau, mais il en DÉPEND : il crée une base — donc
        // v2 depuis `a4c1edaf` — puis la ROUVRE. Si un test voisin tient
        // `OBRAIN_PROPS_V2=0` à cet instant, l'ouverture est REFUSÉE par la
        // garde de `8e15278b` (« zone v2 non vide + régime hérité demandé »),
        // et ce test meurt sur un défaut qui n'est pas le sien.
        //
        // MESURE : sur l'arbre d'avant, 5 suites vertes sur 5 ; avec les six
        // tests de relecture ajoutés ici — qui ouvrent chacun une fenêtre
        // `=0` pour fabriquer un sidecar hérité — 6 suites rouges sur 8, et
        // ce test SEUL, toujours sur la même erreur. La course était déjà là ;
        // elle attendait qu'on élargisse la fenêtre.
        //
        // Le verrou existe exactement pour ça — il ne protège aucun invariant
        // de données, il sérialise `std::env`. On l'étend donc aux LECTEURS du
        // drapeau, pas seulement à ceux qui le posent. Aucune assertion n'est
        // touchée.
        let _guard = props_v2_env_lock();

        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb");

        // --- Write phase ---
        // `generic_vec` is a user-visible vector property that MUST roundtrip.
        // We intentionally avoid `_st_embedding` here because that key is
        // filtered during `load_properties` (see `SKIP_ON_LOAD_PROP_KEYS`);
        // its roundtrip semantics are covered by
        // `skip_on_load_keys_are_dropped_after_reopen` below.
        let (node_id, edge_id, generic_vec) = {
            let s = SubstrateStore::create(&path).unwrap();
            let a = s.create_node(&["Doc"]);
            let b = s.create_node(&["Doc"]);
            let e = s.create_edge(a, b, "LINKS_TO");

            let vec: Arc<[f32]> = Arc::from(vec![0.1_f32, 0.2, -0.3, 0.5].into_boxed_slice());
            s.set_node_property(a, "title", Value::String("hello".into()));
            s.set_node_property(a, "generic_vec", Value::Vector(vec.clone()));
            s.set_node_property(a, "count", Value::Int64(42));
            s.set_edge_property(e, "weight", Value::Float64(0.75));
            s.flush().unwrap();
            (a, e, vec)
        };

        // --- Reopen phase ---
        let s = SubstrateStore::open(&path).unwrap();

        // Node properties
        let title = s
            .get_node_property(node_id, &PropertyKey::new("title"))
            .expect("title should persist");
        assert!(matches!(title, Value::String(ref s) if s.as_str() == "hello"));

        let count = s
            .get_node_property(node_id, &PropertyKey::new("count"))
            .expect("count should persist");
        assert!(matches!(count, Value::Int64(42)));

        let emb = s
            .get_node_property(node_id, &PropertyKey::new("generic_vec"))
            .expect("generic_vec should persist");
        match emb {
            Value::Vector(v) => {
                assert_eq!(&*v, &*generic_vec, "vector value must roundtrip byte-exact");
            }
            other => panic!("expected Vector, got {other:?}"),
        }

        // Edge property
        let w = s
            .get_edge_property(edge_id, &PropertyKey::new("weight"))
            .expect("edge weight should persist");
        assert!(matches!(w, Value::Float64(f) if (f - 0.75).abs() < 1e-12));
    }

    /// T16.7 contract: `Value::Vector` writes — including those named
    /// in `SKIP_ON_LOAD_PROP_KEYS` — are routed to dense mmap'd
    /// `substrate.veccol.*` zones and roundtrip byte-exactly through
    /// a reopen, without going near the bincode `substrate.props`
    /// sidecar. This is the replacement for the pre-T16.7 contract
    /// where `_st_embedding` was silently dropped at load time to
    /// dodge the anon-RSS blow-out.
    ///
    /// Regression guard: if vector routing stops triggering (e.g.
    /// someone removes the `Value::Vector` arm in `set_node_property`),
    /// this test goes red — the vector ends up in the DashMap, hits
    /// `SKIP_ON_LOAD_PROP_KEYS`, and the reopen returns `None` again,
    /// re-introducing the anon-RSS problem.
    #[test]
    fn vector_properties_roundtrip_via_vec_columns_after_reopen() {
        use obrain_core::graph::traits::GraphStore;
        use std::sync::Arc;

        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb");

        let (node_id, expected) = {
            let s = SubstrateStore::create(&path).unwrap();
            let a = s.create_node(&["Doc"]);
            let v: Vec<f32> = (0..8).map(|i| (i as f32) * 0.125).collect();
            let arc: Arc<[f32]> = Arc::from(v.clone().into_boxed_slice());
            s.set_node_property(a, "title", Value::String("persistent".into()));
            s.set_node_property(a, "_st_embedding", Value::Vector(arc));
            s.flush().unwrap();
            (a, v)
        };

        let s = SubstrateStore::open(&path).unwrap();

        // Non-vector key roundtrips through the props sidecar as usual.
        assert!(
            s.get_node_property(node_id, &PropertyKey::new("title"))
                .is_some(),
            "scalar key should roundtrip via the props sidecar"
        );

        // Vector roundtrip: post-T16.7 this is stored in the vec-column
        // zone and hydrated back on open — bytes-exact.
        let got = s
            .get_node_property(node_id, &PropertyKey::new("_st_embedding"))
            .expect("_st_embedding should roundtrip via vec_columns after T16.7");
        match got {
            Value::Vector(arc) => {
                assert_eq!(
                    arc.as_ref(),
                    &expected[..],
                    "vector payload must roundtrip byte-exact"
                );
            }
            other => panic!("expected Value::Vector, got {other:?}"),
        }

        // Every name in `SKIP_ON_LOAD_PROP_KEYS` is still a valid lookup
        // key — the list now only affects legacy bincode-sidecar bases
        // (pre-T16.7 migrations); freshly-written vectors are untouched
        // by it. Exercise the lookup path so a future regression that
        // panics on these keys is caught.
        for key in SKIP_ON_LOAD_PROP_KEYS {
            let _ = s.get_node_property(node_id, &PropertyKey::new(*key));
        }
    }

    /// T16.7 Step 3b — auto-migration regression anchor.
    ///
    /// Simulates a **pre-T16.7 vintage base**: a `SubstrateStore` whose
    /// `substrate.props` sidecar carries a `Value::Vector` payload
    /// written through the old code path (direct bincode serialisation
    /// of the DashMap, no vec-column zone). We fabricate the state by
    /// driving `PropertiesStreamingWriter` directly so we can write a
    /// vector entry without going through the routed setter.
    ///
    /// On reopen, `load_properties` MUST:
    ///   1. Route the vector into the vec-column registry so
    ///      `get_node_property` returns it (byte-exact) via vec_columns.
    ///   2. Keep the DashMap sidecar free of the vector entry — the
    ///      next `flush()` will then re-persist a vector-free sidecar
    ///      via the `persist_properties` defensive filter, completing
    ///      the upgrade.
    ///
    /// If someone reintroduces the pre-Step-3b load path (direct
    /// `entries_to_map` without the vector split) this test goes red:
    /// the vector would end up in the DashMap, the next flush would
    /// drop it from the sidecar (defensive filter) AND from the DashMap
    /// on the subsequent reopen — silent data loss.
    /// ── (2026-08-19) REGIME EXPLICITE : CE SCENARIO EST HERITE ──────────
    ///
    /// Ce test FABRIQUE une base pre-T16.7 en ecrasant `substrate.props` avec
    /// un sidecar herite. Une telle base n a par construction jamais eu de
    /// zone v2 : a son ouverture reelle, `zone_exists` est faux et le sidecar
    /// n est pas vide, donc `base_neuve` est faux — le regime herite s impose
    /// tout seul et l auto-migration s execute.
    ///
    /// Le test, lui, part d un `SubstrateStore::create` : depuis `a4c1edaf`
    /// cette base NAIT en v2, et le `set_node_property` qui suit alloue une
    /// page. `load_properties` voit alors `v2_has_pages` et court-circuite
    /// l hydratation du sidecar — deliberement, v2 faisant autorite. Le test
    /// montait donc un hybride que la production ne peut pas produire.
    ///
    /// PREUVE que c est bien la mise en place et non le code : le jumeau
    /// `auto_migrates_legacy_blobs_on_load` passe VERT sans rien changer — il
    /// n ecrit aucune propriete avant de fabriquer le sidecar, sa zone v2
    /// reste donc a zero page et l hydratation heritee a lieu. Meme code,
    /// meme regime attendu, resultat oppose : la variable est la mise en
    /// place, pas la durabilite.
    ///
    /// On pose donc le regime EXPLICITEMENT au lieu de dependre d un defaut
    /// qui a change sous nos pieds.
    #[test]
    #[allow(unsafe_code)]
    fn auto_migrates_legacy_vectors_on_load() {
        let _guard = props_v2_env_lock();
        // SAFETY: serialise par `props_v2_env_lock`.
        unsafe { std::env::set_var("OBRAIN_PROPS_V2", "0") };
        use crate::props_snapshot::PropertiesStreamingWriter;
        use obrain_core::graph::traits::GraphStore;
        use std::sync::Arc;

        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb");

        // Phase 1 — create a fresh T16.7 store, write ONE node with a
        // scalar (so the node slot exists and labels are persisted),
        // then flush + drop.
        let node_id = {
            let s = SubstrateStore::create(&path).unwrap();
            let a = s.create_node(&["Doc"]);
            s.set_node_property(a, "title", Value::String("legacy".into()));
            s.flush().unwrap();
            a
        };

        // Phase 2 — simulate the pre-T16.7 sidecar state by OVER-
        // WRITING `substrate.props` with a hand-crafted snapshot that
        // contains both the scalar and a vector entry for the same
        // node. Because `PropertiesStreamingWriter` doesn't filter by
        // value kind (it's the post-filter consumer of whatever
        // `persist_properties` feeds it), we get the vector into the
        // sidecar exactly as a v1.x migration would have done.
        let sidecar_path = path.join(PROPS_FILENAME);
        let vec_payload: Vec<f32> = (0..16).map(|i| i as f32 * 0.0625).collect();
        let arc: Arc<[f32]> = Arc::from(vec_payload.clone().into_boxed_slice());
        {
            let mut w = PropertiesStreamingWriter::open(&sidecar_path).unwrap();
            let props: Vec<(String, Value)> = vec![
                ("title".to_string(), Value::String("legacy".into())),
                ("legacy_embedding".to_string(), Value::Vector(arc.clone())),
            ];
            w.append_node(node_id.0, &props).unwrap();
            w.finish().unwrap();
        }

        // Sanity: the raw pre-upgrade sidecar must actually contain the
        // vector key — otherwise this test is not exercising what it
        // claims. Bincode encodes the key as a UTF-8 string, so a byte
        // substring scan is conclusive.
        {
            let raw = std::fs::read(&sidecar_path).unwrap();
            assert!(
                raw.windows(b"legacy_embedding".len())
                    .any(|w| w == b"legacy_embedding"),
                "pre-upgrade sidecar should carry the vector key (test invariant)"
            );
        }

        // Phase 3 — reopen. `load_properties` must route the vector
        // into vec_columns.
        let s = SubstrateStore::open(&path).unwrap();

        // 3a. Vector is readable via vec_columns — byte-exact.
        let got = s
            .get_node_property(node_id, &PropertyKey::new("legacy_embedding"))
            .expect("vector should be auto-migrated to vec_columns on load");
        match got {
            Value::Vector(arc) => {
                assert_eq!(
                    arc.as_ref(),
                    &vec_payload[..],
                    "auto-migrated vector must be byte-exact",
                );
            }
            other => panic!("expected Value::Vector, got {other:?}"),
        }

        // 3b. Scalar still lives on the DashMap sidecar path.
        assert!(
            matches!(
                s.get_node_property(node_id, &PropertyKey::new("title")),
                Some(Value::String(_))
            ),
            "scalar property should still be present after auto-migration"
        );

        // Phase 4 — flush + drop. The defensive filter in
        // `persist_properties` now strips the vector from the
        // re-serialised sidecar.
        s.flush().unwrap();
        drop(s);

        // 4a. Post-flush sidecar must NOT carry the vector key.
        let raw_after = std::fs::read(&sidecar_path).unwrap();
        assert!(
            !raw_after
                .windows(b"legacy_embedding".len())
                .any(|w| w == b"legacy_embedding"),
            "post-flush sidecar must not carry the auto-migrated vector key \
             (bytes len={})",
            raw_after.len(),
        );
        // 4b. The scalar key survives.
        assert!(
            raw_after.windows(b"title".len()).any(|w| w == b"title"),
            "scalar key should still be in the post-flush sidecar"
        );

        // Phase 5 — reopen a THIRD time. The vector must still be
        // readable (now exclusively from the vec-column zone; the
        // sidecar no longer references it).
        let s = SubstrateStore::open(&path).unwrap();
        let got = s
            .get_node_property(node_id, &PropertyKey::new("legacy_embedding"))
            .expect("vector should still be readable after upgrade-then-flush cycle");
        match got {
            Value::Vector(arc) => {
                assert_eq!(arc.as_ref(), &vec_payload[..]);
            }
            other => panic!("expected Value::Vector, got {other:?}"),
        }
    }

    /// [`SubstrateStore::checkpoint`] contract anchor.
    ///
    /// Two guarantees, both load-bearing for offline sidecar migrations:
    ///
    /// 1. **The WAL is actually truncated.** No service called
    ///    [`crate::checkpoint::checkpoint`] before this method existed
    ///    (only the `checkpoint_cli` example, run by hand), so on a
    ///    long-lived base the WAL grew without bound and every open
    ///    replayed it in full — measured at 452 MB / 4.2 M inline
    ///    property writes on a 93 616-node agent base.
    /// 2. **Flush precedes the truncate**, so no committed state is
    ///    lost by discarding the journal: everything the WAL could have
    ///    replayed is already in the zones, dict and sidecar. A crash
    ///    between the two replays the old WAL over an already-current
    ///    state, which is idempotent.
    ///
    /// The migration relevance: a `List(Float64) -> Vector` conversion
    /// of the sidecar is performed offline, with the store closed. Any
    /// pre-conversion value still journalled in the WAL is a candidate
    /// to be replayed over the converted state on the next open, since
    /// `merge_wal_inline_props` runs *after* `load_properties` has done
    /// the routing. Checkpointing before the conversion removes that
    /// class of interference entirely, which is why the documented
    /// procedure is checkpoint → convert → finalize.
    /// ── (2026-08-19) REGIME EXPLICITE : CE SCENARIO EST HERITE ──────────
    ///
    /// Ce test FABRIQUE une base pre-T16.7 en ecrasant `substrate.props` avec
    /// un sidecar herite. Une telle base n a par construction jamais eu de
    /// zone v2 : a son ouverture reelle, `zone_exists` est faux et le sidecar
    /// n est pas vide, donc `base_neuve` est faux — le regime herite s impose
    /// tout seul et l auto-migration s execute.
    ///
    /// Le test, lui, part d un `SubstrateStore::create` : depuis `a4c1edaf`
    /// cette base NAIT en v2, et le `set_node_property` qui suit alloue une
    /// page. `load_properties` voit alors `v2_has_pages` et court-circuite
    /// l hydratation du sidecar — deliberement, v2 faisant autorite. Le test
    /// montait donc un hybride que la production ne peut pas produire.
    ///
    /// PREUVE que c est bien la mise en place et non le code : le jumeau
    /// `auto_migrates_legacy_blobs_on_load` passe VERT sans rien changer — il
    /// n ecrit aucune propriete avant de fabriquer le sidecar, sa zone v2
    /// reste donc a zero page et l hydratation heritee a lieu. Meme code,
    /// meme regime attendu, resultat oppose : la variable est la mise en
    /// place, pas la durabilite.
    ///
    /// On pose donc le regime EXPLICITEMENT au lieu de dependre d un defaut
    /// qui a change sous nos pieds.
    #[test]
    #[allow(unsafe_code)]
    fn checkpoint_truncates_the_wal_without_losing_committed_state() {
        let _guard = props_v2_env_lock();
        // SAFETY: serialise par `props_v2_env_lock`.
        unsafe { std::env::set_var("OBRAIN_PROPS_V2", "0") };
        use crate::props_snapshot::PropertiesStreamingWriter;
        use obrain_core::graph::traits::GraphStore;
        use std::sync::Arc;

        let payload: Vec<f32> = (0..16).map(|i| i as f32 * 0.0625).collect();

        // Rewrites the sidecar so `embedding` is a `Value::Vector` —
        // the offline conversion step, done here inline.
        let vectorise_sidecar = |sidecar: &std::path::Path, node: NodeId| {
            let arc: Arc<[f32]> = Arc::from(payload.clone().into_boxed_slice());
            let mut w = PropertiesStreamingWriter::open(sidecar).unwrap();
            let props: Vec<(String, Value)> = vec![("embedding".to_string(), Value::Vector(arc))];
            w.append_node(node.0, &props).unwrap();
            w.finish().unwrap();
        };

        // A node property written as a numeric `List` — the shape an
        // agent writing through Cypher/JSON actually produces, and the
        // one `route_vector_write` does NOT match. Unlike a `Vector`
        // (which returns before the WAL append) this IS journalled.
        let as_list = || {
            let items: Vec<Value> = payload.iter().map(|f| Value::Float64(*f as f64)).collect();
            Value::List(Arc::from(items.into_boxed_slice()))
        };

        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb");
        let wal_path = path.join("substrate.wal");

        // ---- Guarantee 1: the WAL is truncated. --------------------------
        let node = {
            let s = SubstrateStore::create(&path).unwrap();
            let a = s.create_node(&["Doc"]);
            s.set_node_property(a, "embedding", as_list());
            s.set_node_property(a, "title", Value::String("keep me".into()));
            // Journal some volume so the "before" offset is unambiguous.
            for i in 0..64 {
                let n = s.create_node(&["Filler"]);
                s.set_node_property(n, "i", Value::Int64(i));
            }
            s.flush().unwrap();

            let wal_before_bytes = std::fs::metadata(&wal_path).unwrap().len();
            let stats = s.checkpoint().unwrap();
            let wal_after_bytes = std::fs::metadata(&wal_path).unwrap().len();

            assert!(
                stats.wal_offset_before > 0,
                "test invariant: the WAL must have carried the writes above"
            );
            assert!(
                wal_after_bytes < wal_before_bytes,
                "checkpoint must shrink the WAL on disk ({wal_before_bytes} -> \
                 {wal_after_bytes} bytes). An unbounded WAL is replayed in full \
                 on every open — that is the cost this method exists to bound."
            );
            a
        };

        // ---- Guarantee 2: nothing committed was lost. --------------------
        {
            let s = SubstrateStore::open(&path).unwrap();
            assert!(
                matches!(
                    s.get_node_property(node, &PropertyKey::new("title")),
                    Some(Value::String(_))
                ),
                "scalar written before the checkpoint must survive discarding \
                 the journal — flush() runs first precisely so it does"
            );
            assert!(
                s.get_node_property(node, &PropertyKey::new("embedding"))
                    .is_some(),
                "the List property must survive the checkpoint too"
            );
        }

        // ---- Migration relevance: convert offline, then reopen. ----------
        // With the journal truncated there is nothing left to replay over
        // the conversion, so `load_properties` routing is the last word.
        vectorise_sidecar(&path.join(PROPS_FILENAME), node);

        let s = SubstrateStore::open(&path).unwrap();
        s.flush().unwrap();
        drop(s);

        let s = SubstrateStore::open(&path).unwrap();
        match s.get_node_property(node, &PropertyKey::new("embedding")) {
            Some(Value::Vector(arc)) => {
                assert_eq!(
                    arc.as_ref(),
                    &payload[..],
                    "converted vector must survive the reopen byte-exact, \
                     served from the vec-column zone"
                );
            }
            other => panic!("expected the converted Value::Vector; got {other:?}"),
        }
    }

    /// T16.7 Step 4d — blob auto-migration regression anchor.
    ///
    /// Mirror of [`auto_migrates_legacy_vectors_on_load`] for the
    /// variable-length blob path: an oversized `Value::String` (bigger
    /// than [`BLOB_COLUMN_THRESHOLD_BYTES`]) sitting in a pre-T16.7.4
    /// `substrate.props` sidecar must auto-migrate into the
    /// [`BlobColumnRegistry`] on open, and the next `flush()` must
    /// evict it from the sidecar. A `Value::Bytes` variant is exercised
    /// to prove the 1-byte type tag preserves the distinction.
    #[test]
    #[allow(unsafe_code)]
    fn auto_migrates_legacy_blobs_on_load() {
        use crate::props_snapshot::PropertiesStreamingWriter;
        use obrain_core::graph::traits::GraphStore;
        use std::sync::Arc;

        // (2026-08-21) CE TEST NE POSAIT PAS SON RÉGIME, ET NE PASSAIT QUE PAR
        // ACCIDENT.
        //
        // Il éprouve la migration d'un sidecar `substrate.props` HÉRITÉ, donc
        // il exige `OBRAIN_PROPS_V2=0`. Il ne le posait pas : il héritait de ce
        // qu'un test voisin avait laissé dans l'environnement du PROCESSUS.
        //
        // Mesuré :
        //     variable non posée -> ÉCHEC
        //     OBRAIN_PROPS_V2=0  -> OK
        //     OBRAIN_PROPS_V2=1  -> ÉCHEC
        //
        // D'où : échec systématique en isolation, et 2 succès sur 4 dans la
        // suite complète, selon l'ordonnancement. Un test qui ne passe que
        // grâce à ses voisins ne teste plus ce qu'il annonce — et le hook de
        // pré-commit, qui lance la suite entière, le voyait passer une fois sur
        // deux. Il aurait laissé filer une vraie régression avec la même
        // probabilité.
        //
        // Le pavé de `props_v2_env_lock` énonce pourtant la règle : « chaque
        // test repose le drapeau qu'il veut dès son entrée ».
        //
        // CE QUE CE TEST GARDE DÉSORMAIS, ET CE QU'IL NE GARDE PLUS.
        // PropsZone v2 est le régime PAR DÉFAUT ; la DashMap de propriétés a
        // disparu. En épinglant `=0`, ce test continue d'éprouver ce qu'il
        // annonce — la migration d'un sidecar `substrate.props` HÉRITÉ — mais
        // il n'éprouve plus le chemin d'ouverture par défaut. Le rendre
        // déterministe vaut mieux que de le laisser passer une fois sur deux ;
        // ce n'est pas la même chose que de le rendre pertinent. Le jour où le
        // régime hérité est retiré, ce test part avec lui, et il faudra un
        // équivalent sous v2 — sans quoi la migration des blobs cesse d'être
        // couverte sans que personne ne le remarque.
        let _garde_env = props_v2_env_lock();
        // SAFETY: sérialisé par `props_v2_env_lock`.
        unsafe { std::env::set_var("OBRAIN_PROPS_V2", "0") };

        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb");

        // Phase 1 — fresh T16.7.4 store, allocate a node slot so the
        // auto-migration has a live target to write into.
        let (node_id_str, node_id_bytes) = {
            let s = SubstrateStore::create(&path).unwrap();
            let a = s.create_node(&["Chat"]);
            let b = s.create_node(&["Chat"]);
            s.flush().unwrap();
            (a, b)
        };

        // Phase 2 — overwrite `substrate.props` with a hand-crafted
        // snapshot carrying BOTH an oversized string and an oversized
        // byte payload. These are the exact shape of pre-T16.7.4 data
        // coming out of `obrain-migrate` on a PO chat history.
        let sidecar_path = path.join(PROPS_FILENAME);
        let big_string: String = "chat payload éclair ".repeat(100); // ~2 KiB
        let big_bytes: Vec<u8> = (0..2048u32).map(|i| (i & 0xff) as u8).collect();
        let bytes_arc: Arc<[u8]> = Arc::from(big_bytes.clone());
        assert!(big_string.len() > BLOB_COLUMN_THRESHOLD_BYTES);
        assert!(big_bytes.len() > BLOB_COLUMN_THRESHOLD_BYTES);
        {
            let mut w = PropertiesStreamingWriter::open(&sidecar_path).unwrap();
            let props_a: Vec<(String, Value)> = vec![
                ("title".to_string(), Value::String("keep me inline".into())),
                (
                    "data".to_string(),
                    Value::String(big_string.as_str().into()),
                ),
            ];
            w.append_node(node_id_str.0, &props_a).unwrap();
            let props_b: Vec<(String, Value)> =
                vec![("blob".to_string(), Value::Bytes(bytes_arc.clone()))];
            w.append_node(node_id_bytes.0, &props_b).unwrap();
            w.finish().unwrap();
        }

        // Sanity: pre-upgrade sidecar must carry BOTH blob keys.
        {
            let raw = std::fs::read(&sidecar_path).unwrap();
            assert!(
                raw.windows(b"data".len()).any(|w| w == b"data"),
                "pre-upgrade sidecar should carry the `data` key"
            );
            assert!(
                raw.windows(b"blob".len()).any(|w| w == b"blob"),
                "pre-upgrade sidecar should carry the `blob` key"
            );
        }

        // Phase 3 — reopen. `load_properties` must route the two
        // oversized entries into blob_columns.
        let s = SubstrateStore::open(&path).unwrap();

        // 3a. Big string is readable via blob_columns, byte-exact.
        let got = s
            .get_node_property(node_id_str, &PropertyKey::new("data"))
            .expect("big string should auto-migrate on load");
        match got {
            Value::String(ref arc) => assert_eq!(arc.as_str(), big_string),
            other => panic!("expected Value::String, got {other:?}"),
        }
        // 3b. Big bytes are readable via blob_columns, byte-exact —
        //     AND must come back as Value::Bytes (not Value::String).
        let got = s
            .get_node_property(node_id_bytes, &PropertyKey::new("blob"))
            .expect("big bytes should auto-migrate on load");
        match got {
            Value::Bytes(arc) => assert_eq!(arc.as_ref(), big_bytes.as_slice()),
            other => panic!("expected Value::Bytes, got {other:?}"),
        }
        // 3c. Short scalar still lives on the DashMap sidecar path.
        match s.get_node_property(node_id_str, &PropertyKey::new("title")) {
            Some(Value::String(arc)) => assert_eq!(arc.as_str(), "keep me inline"),
            other => panic!("expected inline Value::String, got {other:?}"),
        }

        // Phase 4 — flush + drop. Defensive filter must strip both
        // blob entries from the rewritten sidecar.
        s.flush().unwrap();
        drop(s);

        let raw_after = std::fs::read(&sidecar_path).unwrap();
        // The scalar key survives.
        assert!(
            raw_after.windows(b"title".len()).any(|w| w == b"title"),
            "short scalar key should still be in the post-flush sidecar"
        );
        // The blob keys do NOT.
        assert!(
            !raw_after.windows(b"data".len()).any(|w| w == b"data"),
            "post-flush sidecar must not carry the auto-migrated `data` key \
             (bytes len={})",
            raw_after.len()
        );
        assert!(
            !raw_after.windows(b"blob".len()).any(|w| w == b"blob"),
            "post-flush sidecar must not carry the auto-migrated `blob` key \
             (bytes len={})",
            raw_after.len()
        );

        // Phase 5 — reopen a third time. The blob columns must still
        // satisfy reads (hydrated from dict v4, no sidecar fallback).
        let s = SubstrateStore::open(&path).unwrap();
        match s.get_node_property(node_id_str, &PropertyKey::new("data")) {
            Some(Value::String(arc)) => assert_eq!(arc.as_str(), big_string),
            other => panic!("expected persisted Value::String after second reopen, got {other:?}"),
        }
        match s.get_node_property(node_id_bytes, &PropertyKey::new("blob")) {
            Some(Value::Bytes(arc)) => {
                assert_eq!(arc.as_ref(), big_bytes.as_slice());
            }
            other => panic!("expected persisted Value::Bytes after second reopen, got {other:?}"),
        }
    }

    /// T16.7 Step 4d — fresh writes also route, not just legacy load.
    /// Ensures `set_node_property` on an oversized Value::String /
    /// Value::Bytes never touches the DashMap (= never lands in the
    /// bincode sidecar) and that reads come back byte-exact.
    #[test]
    fn fresh_blob_writes_bypass_sidecar() {
        use obrain_core::graph::traits::GraphStore;
        use std::sync::Arc;

        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb");
        let big_string: String = "éclair ".repeat(200); // > 256 B
        let big_bytes: Vec<u8> = (0..1024u32).map(|i| ((i * 7) & 0xff) as u8).collect();

        let (nid, eid) = {
            let s = SubstrateStore::create(&path).unwrap();
            let a = s.create_node(&["Doc"]);
            let b = s.create_node(&["Doc"]);
            let e = s.create_edge(a, b, "REL");
            s.set_node_property(a, "data", Value::String(big_string.as_str().into()));
            s.set_edge_property(e, "blob", Value::Bytes(Arc::from(big_bytes.clone())));
            s.flush().unwrap();
            (a, e)
        };

        // Sidecar must NOT contain either blob key.
        let sidecar = std::fs::read(path.join(PROPS_FILENAME)).unwrap();
        assert!(
            !sidecar.windows(b"data".len()).any(|w| w == b"data"),
            "fresh oversized String must not land in substrate.props"
        );
        assert!(
            !sidecar.windows(b"blob".len()).any(|w| w == b"blob"),
            "fresh oversized Bytes must not land in substrate.props"
        );

        // Reopen and verify byte-exact reads.
        let s = SubstrateStore::open(&path).unwrap();
        match s.get_node_property(nid, &PropertyKey::new("data")) {
            Some(Value::String(arc)) => assert_eq!(arc.as_str(), big_string),
            other => panic!("expected String, got {other:?}"),
        }
        match s.get_edge_property(eid, &PropertyKey::new("blob")) {
            Some(Value::Bytes(arc)) => {
                assert_eq!(arc.as_ref(), big_bytes.as_slice());
            }
            other => panic!("expected Bytes, got {other:?}"),
        }
    }

    #[test]
    fn create_node_returns_nonzero_increasing_ids() {
        let (_td, s) = store();
        let a = s.create_node(&["Person"]);
        let b = s.create_node(&["Person"]);
        let c = s.create_node(&["Company"]);
        assert_ne!(a.0, 0);
        assert_ne!(b.0, 0);
        assert_ne!(c.0, 0);
        assert!(a.0 < b.0 && b.0 < c.0);
    }

    #[test]
    fn create_node_no_labels() {
        let (_td, s) = store();
        let id = s.create_node(&[]);
        let n = s.get_node(id).unwrap();
        assert!(n.labels.is_empty());
        assert_eq!(n.id, id);
    }

    #[test]
    fn get_node_returns_labels_and_empty_props() {
        let (_td, s) = store();
        let id = s.create_node(&["Person", "Employee"]);
        let n = s.get_node(id).unwrap();
        assert_eq!(n.id, id);
        assert_eq!(n.labels.len(), 2);
        let names: Vec<&str> = n.labels.iter().map(|l| l.as_str()).collect();
        assert!(names.contains(&"Person") && names.contains(&"Employee"));
        assert!(n.properties.is_empty());
    }

    #[test]
    fn set_and_get_node_property() {
        let (_td, s) = store();
        let id = s.create_node(&["Person"]);
        s.set_node_property(id, "name", Value::from("Alix"));
        s.set_node_property(id, "age", Value::Int64(30));

        let name = s.get_node_property(id, &PropertyKey::new("name")).unwrap();
        let age = s.get_node_property(id, &PropertyKey::new("age")).unwrap();
        assert_eq!(name, Value::from("Alix"));
        assert_eq!(age, Value::Int64(30));

        // Full-object read carries all props.
        let n = s.get_node(id).unwrap();
        assert_eq!(n.properties.len(), 2);
    }

    #[test]
    fn set_overwrites_existing_property() {
        let (_td, s) = store();
        let id = s.create_node(&["Person"]);
        s.set_node_property(id, "age", Value::Int64(30));
        s.set_node_property(id, "age", Value::Int64(31));
        let age = s.get_node_property(id, &PropertyKey::new("age")).unwrap();
        assert_eq!(age, Value::Int64(31));
    }

    #[test]
    fn remove_node_property_returns_previous_value() {
        let (_td, s) = store();
        let id = s.create_node(&["Person"]);
        s.set_node_property(id, "age", Value::Int64(30));
        let prev = s.remove_node_property(id, "age").unwrap();
        assert_eq!(prev, Value::Int64(30));
        assert!(s.get_node_property(id, &PropertyKey::new("age")).is_none());
    }

    #[test]
    fn remove_missing_property_returns_none() {
        let (_td, s) = store();
        let id = s.create_node(&["Person"]);
        assert!(s.remove_node_property(id, "nope").is_none());
    }

    #[test]
    fn delete_node_is_idempotent_and_hides_it() {
        let (_td, s) = store();
        let id = s.create_node(&["Person"]);
        assert!(s.delete_node(id));
        assert!(s.get_node(id).is_none());
        // Second delete is a no-op.
        assert!(!s.delete_node(id));
    }

    #[test]
    fn set_property_on_deleted_node_is_ignored() {
        let (_td, s) = store();
        let id = s.create_node(&["Person"]);
        s.delete_node(id);
        // LpgStore silently no-ops; we match.
        s.set_node_property(id, "name", Value::from("ghost"));
        assert!(s.get_node_property(id, &PropertyKey::new("name")).is_none());
    }

    #[test]
    fn node_count_tracks_live_nodes() {
        let (_td, s) = store();
        assert_eq!(s.node_count(), 0);
        let a = s.create_node(&["A"]);
        let _b = s.create_node(&["B"]);
        let _c = s.create_node(&["C"]);
        assert_eq!(s.node_count(), 3);
        s.delete_node(a);
        assert_eq!(s.node_count(), 2);
    }

    #[test]
    fn node_ids_is_sorted_and_excludes_tombstones() {
        let (_td, s) = store();
        let a = s.create_node(&["A"]);
        let b = s.create_node(&["A"]);
        let c = s.create_node(&["A"]);
        s.delete_node(b);
        let ids = s.node_ids();
        assert_eq!(ids, vec![a, c]);
    }

    #[test]
    fn recount_repare_un_compteur_qui_a_derive() {
        // On FABRIQUE la dérive observée en production : le compteur atomique
        // dit moins que ce que portent les enregistrements. C'est exactement
        // la situation d'une base v5+ dont l'instantané a figé une valeur
        // fausse — plus rien, ensuite, ne la confronte au disque.
        let (_td, s) = store();
        s.create_node(&["Person"]);
        s.create_node(&["Person"]);
        s.create_node(&["Person"]);
        assert_eq!(s.node_count_by_label("Person"), 3, "point de départ sain");

        let bit = s.labels.read().bit_for("Person").expect("label interné") as usize;
        s.label_live_counts[bit].store(1, Ordering::Relaxed);
        assert_eq!(s.node_count_by_label("Person"), 1, "dérive installée");
        assert_eq!(
            s.nodes_by_label("Person").len(),
            3,
            "le SCAN, lui, n'a jamais menti — c'est ce qui rend la dérive détectable"
        );

        let ecarts = s.recount_live_counters().expect("recount");
        assert_eq!(
            s.node_count_by_label("Person"),
            3,
            "compteur remis d'accord avec le disque"
        );
        assert!(
            ecarts
                .iter()
                .any(|(n, avant, apres)| n == "Person" && *avant == 1 && *apres == 3),
            "l'écart doit être RAPPORTÉ, pas corrigé en silence : {ecarts:?}"
        );
    }

    /// Le pendant du test précédent, côté ARÊTES. Il n'existait pas : la
    /// reconstruction réparait `total_live_edges` et `edge_type_live_counts`
    /// au passage, mais sans jamais dire qu'elle l'avait fait. Tant que
    /// personne ne lisait ces compteurs c'était sans conséquence ; ça cesse
    /// de l'être dès qu'une requête y répond.
    #[test]
    fn recount_rapporte_une_derive_du_compteur_d_aretes() {
        let (_td, s) = store();
        let a = s.create_node(&["A"]);
        let b = s.create_node(&["B"]);
        s.create_edge(a, b, "LIE");
        s.create_edge(b, a, "LIE");
        s.create_edge(a, b, "AUTRE");
        assert_eq!(s.edge_count(), 3, "point de départ sain");
        assert_eq!(s.live_count_by_edge_type("LIE"), 2);

        // On FABRIQUE la dérive : le compteur global dit moins que le disque.
        s.total_live_edges.store(1, Ordering::Relaxed);
        assert_eq!(s.edge_count(), 1, "dérive installée");

        let ecarts = s.recount_live_counters().expect("recount");
        assert_eq!(s.edge_count(), 3, "compteur remis d'accord avec le disque");
        assert!(
            ecarts
                .iter()
                .any(|(n, avant, apres)| n.contains("total") && *avant == 1 && *apres == 3),
            "l'écart du total d'arêtes doit être RAPPORTÉ : {ecarts:?}"
        );
    }

    /// Un compteur PAR TYPE qui ment doit être rapporté nommément — sinon on
    /// sait qu'« il y a eu une dérive » sans savoir laquelle, et
    /// `type(r), count(r)` continuerait d'inventer un nombre pour ce type-là.
    #[test]
    fn recount_rapporte_une_derive_par_type_d_arete() {
        let (_td, s) = store();
        let a = s.create_node(&["A"]);
        let b = s.create_node(&["B"]);
        s.create_edge(a, b, "LIE");
        s.create_edge(b, a, "LIE");
        s.create_edge(a, b, "AUTRE");
        assert_eq!(s.live_count_by_edge_type("LIE"), 2);

        let id_lie = s.edge_types.read().id_for("LIE").expect("type interné");
        s.edge_type_live_counts
            .get(&id_lie)
            .expect("compteur présent")
            .store(99, Ordering::Relaxed);
        assert_eq!(s.live_count_by_edge_type("LIE"), 99, "dérive installée");

        let ecarts = s.recount_live_counters().expect("recount");
        assert_eq!(s.live_count_by_edge_type("LIE"), 2, "compteur réparé");
        assert!(
            ecarts
                .iter()
                .any(|(n, avant, apres)| n.contains("LIE") && *avant == 99 && *apres == 2),
            "l'écart doit nommer LE TYPE, pas seulement signaler une dérive : {ecarts:?}"
        );
    }

    /// Le cas que le seul parcours des compteurs d'avant manquerait : un type
    /// entièrement ABSENT de la table, donc à zéro implicite, alors qu'il
    /// porte des arêtes vivantes. C'est la forme exacte du `count: 0` inventé
    /// que raconte le commentaire d'`edge_counts_by_type`.
    #[test]
    fn recount_rapporte_un_type_absent_de_la_table_des_compteurs() {
        let (_td, s) = store();
        let a = s.create_node(&["A"]);
        let b = s.create_node(&["B"]);
        s.create_edge(a, b, "OUBLIE");
        assert_eq!(s.live_count_by_edge_type("OUBLIE"), 1);

        let id = s.edge_types.read().id_for("OUBLIE").expect("type interné");
        s.edge_type_live_counts.remove(&id);
        assert_eq!(
            s.live_count_by_edge_type("OUBLIE"),
            0,
            "absent de la table = zéro, et c'est un MENSONGE"
        );

        let ecarts = s.recount_live_counters().expect("recount");
        assert_eq!(s.live_count_by_edge_type("OUBLIE"), 1, "réparé");
        assert!(
            ecarts
                .iter()
                .any(|(n, avant, apres)| n.contains("OUBLIE") && *avant == 0 && *apres == 1),
            "un type apparu à la reconstruction doit être rapporté : {ecarts:?}"
        );
    }

    /// `edge_counts_by_type` répond désormais depuis les compteurs. Ce test
    /// vérifie qu'elle rend LA MÊME CHOSE que le balayage qu'elle remplace —
    /// c'est la seule question qui vaille, la vitesse ne rachetant jamais un
    /// nombre faux.
    ///
    /// Le balayage de référence est reproduit ici plutôt qu'appelé : il n'est
    /// plus dans le code de production, et c'est précisément pour cela qu'il
    /// faut le garder sous la main dans le test.
    #[test]
    fn edge_counts_by_type_egale_le_balayage_qu_elle_remplace() {
        let (_td, s) = store();
        let a = s.create_node(&["A"]);
        let b = s.create_node(&["B"]);
        let c = s.create_node(&["C"]);
        s.create_edge(a, b, "LIE");
        s.create_edge(b, c, "LIE");
        s.create_edge(c, a, "LIE");
        s.create_edge(a, c, "AUTRE");
        let mort = s.create_edge(b, a, "EPHEMERE");
        s.delete_edge(mort);

        // Le balayage de référence, tel qu'il était écrit.
        let borne = s.next_edge_id.load(Ordering::Acquire);
        let mut attendu: std::collections::HashMap<String, usize> =
            std::collections::HashMap::new();
        for slot in 1..borne {
            let Ok(Some(rec)) = s.writer.read_edge(slot) else {
                continue;
            };
            if rec.flags & crate::record::edge_flags::TOMBSTONED != 0 {
                continue;
            }
            *attendu
                .entry(s.resolve_edge_type_by_id(rec.edge_type).to_string())
                .or_insert(0) += 1;
        }

        let obtenu = s.edge_counts_by_type().expect("le substrat sait compter");
        assert_eq!(
            obtenu, attendu,
            "les compteurs doivent rendre exactement ce que rendait le balayage"
        );
        assert_eq!(obtenu.get("LIE"), Some(&3));
        assert_eq!(obtenu.get("AUTRE"), Some(&1));
        assert!(
            !obtenu.contains_key("EPHEMERE"),
            "un type sans arête vivante est OMIS, comme le faisait le balayage"
        );
        // Et la somme doit s'accorder avec le compteur global.
        assert_eq!(obtenu.values().sum::<usize>(), s.edge_count());
    }

    /// LE FAUX RÉSULTAT QUI ÉTAIT EN PRODUCTION.
    ///
    /// `add_label` posait le bit sur disque sans incrémenter le compteur.
    /// Symptôme mesuré : après `SET n:B` sur 40 nœuds, `MATCH (n:B) RETURN
    /// count(n)` rendait 0 — il prend le raccourci O(1) — pendant que
    /// `MATCH (n:B) RETURN n.v` rendait 40 lignes. Deux réponses à la même
    /// question selon le plan choisi.
    ///
    /// Le test confronte donc systématiquement le COMPTEUR au BALAYAGE : c'est
    /// le seul contrôle qui aurait attrapé le défaut, et le seul qui
    /// attrapera sa réapparition.
    #[test]
    fn ajouter_un_label_fait_suivre_le_compteur() {
        let (_td, s) = store();
        let ids: Vec<NodeId> = (0..40).map(|_| s.create_node(&["A"])).collect();
        assert_eq!(s.node_count_by_label("A"), 40);
        assert_eq!(s.node_count_by_label("B"), 0);

        for id in &ids {
            assert!(s.add_label(*id, "B"), "le label doit être posé");
        }

        assert_eq!(
            s.nodes_by_label("B").len(),
            40,
            "le BALAYAGE voit les 40 — il n'a jamais menti"
        );
        assert_eq!(
            s.node_count_by_label("B"),
            40,
            "et le COMPTEUR doit dire la même chose : c'est lui qui rendait 0"
        );
        // Le label d'origine ne doit pas avoir bougé.
        assert_eq!(s.node_count_by_label("A"), 40);
        // Et le recomptage ne doit rien avoir à corriger.
        assert!(
            s.recount_live_counters().expect("recount").is_empty(),
            "compteurs et disque doivent déjà s'accorder"
        );
    }

    #[test]
    fn retirer_un_label_fait_suivre_le_compteur() {
        let (_td, s) = store();
        let ids: Vec<NodeId> = (0..10).map(|_| s.create_node(&["A", "B"])).collect();
        assert_eq!(s.node_count_by_label("B"), 10);

        for id in ids.iter().take(4) {
            assert!(s.remove_label(*id, "B"));
        }

        assert_eq!(s.nodes_by_label("B").len(), 6, "balayage");
        assert_eq!(s.node_count_by_label("B"), 6, "compteur");
        assert_eq!(s.node_count_by_label("A"), 10, "le voisin ne bouge pas");
        assert!(s.recount_live_counters().expect("recount").is_empty());
    }

    /// L'idempotence ne doit pas compter deux fois — un `SET n:B` répété sur
    /// un nœud qui porte déjà B ferait sinon dériver le compteur à la hausse,
    /// et c'est le sens de dérive le plus difficile à remarquer.
    #[test]
    fn poser_deux_fois_le_meme_label_ne_compte_qu_une_fois() {
        let (_td, s) = store();
        let n = s.create_node(&["A"]);
        assert!(s.add_label(n, "B"));
        assert!(!s.add_label(n, "B"), "second appel : sans effet");
        assert!(!s.add_label(n, "B"), "troisième : idem");
        assert_eq!(s.node_count_by_label("B"), 1);
        assert_eq!(s.nodes_by_label("B").len(), 1);

        assert!(s.remove_label(n, "B"));
        assert!(!s.remove_label(n, "B"), "retrait répété : sans effet");
        assert_eq!(s.node_count_by_label("B"), 0);
        assert!(s.recount_live_counters().expect("recount").is_empty());
    }

    /// LE TEST DE PARITÉ QUE LES AGENTS RÉCLAMENT, et qui garde la porte du
    /// raccourci de comptage d'arêtes.
    ///
    /// Un test qui monte une base NEUVE ne peut pas voir la dérive des
    /// compteurs : ils viennent d'être incrémentés, donc ils sont justes par
    /// construction. C'est exactement pourquoi
    /// `edge_counts_by_type_egale_le_balayage_qu_elle_remplace` n'a rien vu
    /// pendant qu'une copie de la base `agent` annonçait `IN_MISSION` à 4 660
    /// pour 2 347 arêtes réelles.
    ///
    /// Celui-ci FLUSHE puis ROUVRE, ce qui fait passer les compteurs par
    /// l'instantané — le chemin où une valeur fausse se fige. Tant qu'il
    /// passe sur une base neuve il ne prouve rien de la production ; le jour
    /// où il rougit, il aura attrapé la régression.
    /// ── DEFAUT EPINGLE : LE BALAYAGE NE SAIT PAS CE QU'IL COMPTE ──────
    ///
    /// `create_node_in_community` alloue par PAGE : le premier insert d'une
    /// communaute arrondit au bord de page (`NODES_PER_PAGE` = 128), laissant
    /// derriere lui des creneaux JAMAIS ECRITS. Une zone mmappee est remplie de
    /// zeros, donc `read_node` rend `Ok(Some(NodeRecord::default()))` pour ces
    /// creneaux : `flags == 0`, donc PAS tombstone.
    ///
    /// `rebuild_live_counters_interne` — le recompte que `open()` execute sans
    /// condition — n'exclut que les tombstones. Il compte donc chaque trou
    /// comme un noeud vivant. MESURE ci-dessous : 10 noeuds crees, 132
    /// annonces apres recompte.
    ///
    /// ── POURQUOI CE N'EST PAS CORRIGE ICI ──
    ///
    /// Il n'existe AUCUN moyen de distinguer un creneau jamais ecrit d'un
    /// noeud reel sans etiquette. `NodeRecord` n'a pas de drapeau « alloue » —
    /// `node_flags` porte TOMBSTONED, CENTRALITY_STALE, EMBEDDING_STALE,
    /// ENGRAM_SEED, HILBERT_DIRTY, IDENTITY, et rien qui dise « ce creneau a
    /// ete ecrit ». Or `create_node(&[])` et `create_node_in_community(&[], 0)`
    /// produisent un enregistrement tout a zero, byte pour byte identique a un
    /// trou. Le balayage ne PEUT PAS trancher.
    ///
    /// Le corriger demande un drapeau ALLOCATED dans `NodeRecord`, donc une
    /// evolution du format d'enregistrement et une migration. C'est une
    /// decision de conception, pas une retouche.
    ///
    /// Le cote ARETES a recu l'exclusion equivalente le 2026-08-21 (« les
    /// aretes pendantes ne sont pas comptees », creneau nul en source ou en
    /// cible). Le cote NOEUDS ne l'a jamais recue, parce qu'elle n'y est pas
    /// exprimable.
    ///
    /// ── PORTEE REELLE ──
    ///
    /// `create_node_in_community` n'est appele par AUCUN chemin de production :
    /// uniquement des tests, des bancs et `geometric.rs`. Le chemin nominal
    /// `create_node` fait un tail-append sans trou, et ne declenche donc pas ce
    /// defaut. C'est un piege latent, pas une panne en cours — mais il attend
    /// le premier appelant de production.
    #[test]
    fn un_trou_de_slot_community_est_compte_comme_un_noeud_vivant() {
        let (_td, s) = store();
        for _ in 0..5 {
            s.create_node_in_community(&["N"], 1);
        }
        for _ in 0..5 {
            s.create_node_in_community(&["N"], 2);
        }

        // Le compteur INCREMENTAL, lui, dit vrai : 10 noeuds crees, 10 comptes.
        // (C'est l'increment ajoute le 2026-09-11 ; sans lui il dirait 0.)
        assert_eq!(
            s.total_live_nodes.load(Ordering::Relaxed),
            10,
            "le compteur incremental compte ce qui a ete cree"
        );

        // (jalon 1) Le RECOMPTE PAR BALAYAGE ne compte PLUS les trous :
        // sans ALLOCATED, un creneau jamais ecrit n existe pas. Ce test
        // verifiait le defaut (132 creneaux annonces pour 10 noeuds) ; il
        // verifie desormais la guerison, comme son message l exigeait.
        s.rebuild_counts_only().expect("recompte");
        let apres = s.total_live_nodes.load(Ordering::Relaxed);
        assert_eq!(
            apres, 10,
            "le balayage ne compte que les creneaux ALLOUES : 10 noeuds, 10 comptes"
        );

        // Les compteurs PAR ETIQUETTE, eux, restent justes : un trou porte
        // `label_bitset == 0`, donc il n'allume aucun bit. C'est precisement
        // pourquoi la somme des compteurs de labels ne peut pas servir a
        // valider `total_live_nodes`.
        assert_eq!(
            s.node_count_by_label("N"),
            10,
            "les compteurs par etiquette sont immunises : un trou n'allume aucun bit"
        );
    }

    /// ── LA RECONCILIATION D'OUVERTURE, MISE A L'EPREUVE ───────────────
    ///
    /// Le doc-comment de `recount_live_counters` (plus haut) affirme encore :
    /// « Des la v5, les compteurs sont restaures en O(1) depuis l'instantane
    /// et le scan n'est plus jamais rejoue : une valeur fausse ecrite une fois
    /// est restauree puis re-persistee a l'identique, indefiniment. »
    ///
    /// CE N'EST PLUS VRAI, et ce test est la pour que ca le reste. `open()`
    /// appelle `rebuild_counts_only()` SANS CONDITION, apres les fusions de
    /// WAL — c'est le premier point ou le filigrane depasse l'instantane, donc
    /// le premier ou « recompter » veut dire quelque chose.
    ///
    /// Le scenario reproduit ici est le scenario REEL : un compteur faux est
    /// persiste (un arret brutal pendant une ecriture produit le meme effet),
    /// la base rouvre, et la question est de savoir si le mensonge survit.
    ///
    /// On MENT DELIBEREMENT aux quatre familles de compteurs avant le flush,
    /// dans les deux sens — trop haut ET trop bas — parce qu'une
    /// reconciliation qui ne saurait que corriger vers le haut laisserait
    /// passer la moitie des derives. Celle mesuree en production etait dans
    /// les deux sens : `IN_MISSION` a 4 660 pour 2 347 reelles, et un label a
    /// 1 220 pour 1 840 reels.
    #[test]
    fn un_compteur_faux_persiste_ne_survit_pas_a_la_reouverture() {
        let td = tempfile::tempdir().unwrap();
        let chemin = td.path().join("kb");

        let (attendus_noeuds, attendus_aretes, bit_a, id_lie) = {
            let s = SubstrateStore::create(&chemin).unwrap();
            let a = s.create_node(&["A"]);
            let b = s.create_node(&["A", "B"]);
            let c = s.create_node(&["B"]);
            s.create_edge(a, b, "LIE");
            s.create_edge(b, c, "LIE");
            s.create_edge(c, a, "AUTRE");

            let bit_a = s.labels.read().bit_for("A").expect("A interne") as usize;
            let id_lie = s.edge_types.read().id_for("LIE").expect("LIE interne");

            // Les valeurs JUSTES, relevees avant le mensonge.
            let n = s.total_live_nodes.load(Ordering::Relaxed);
            let e = s.total_live_edges.load(Ordering::Relaxed);
            assert_eq!(
                (n, e),
                (3, 3),
                "temoin : la base est bien celle qu'on croit"
            );
            assert_eq!(s.label_live_counts[bit_a].load(Ordering::Relaxed), 2);

            // ── LE MENSONGE, avant le flush qui le persiste. ──
            s.total_live_nodes.store(999, Ordering::Relaxed); // trop haut
            s.total_live_edges.store(1, Ordering::Relaxed); // trop bas
            s.label_live_counts[bit_a].store(1220, Ordering::Relaxed); // le cas mesure
            s.edge_type_live_counts
                .entry(id_lie)
                .or_default()
                .store(4660, Ordering::Relaxed); // le cas `IN_MISSION`

            s.flush().expect("flush — c'est lui qui grave le mensonge");
            (n, e, bit_a, id_lie)
        };

        // La base rouvre. `open()` doit confronter les compteurs au disque.
        let s = SubstrateStore::open(&chemin).expect("reouverture");

        assert_eq!(
            s.total_live_nodes.load(Ordering::Relaxed),
            attendus_noeuds,
            "total_live_nodes doit etre reconcilie a l'ouverture, pas restaure"
        );
        assert_eq!(
            s.total_live_edges.load(Ordering::Relaxed),
            attendus_aretes,
            "total_live_edges doit etre reconcilie a l'ouverture"
        );
        assert_eq!(
            s.label_live_counts[bit_a].load(Ordering::Relaxed),
            2,
            "le compteur de label doit etre reconcilie (le cas 1220 vs 1840)"
        );
        assert_eq!(
            s.edge_type_live_counts
                .get(&id_lie)
                .map(|a| a.load(Ordering::Relaxed))
                .unwrap_or(0),
            2,
            "le compteur par type doit etre reconcilie (le cas IN_MISSION)"
        );

        // Et les accesseurs publics, qui sont ce que voit le planificateur.
        assert_eq!(s.node_count(), 3);
        assert_eq!(s.edge_count(), 3);
        assert_eq!(s.node_count_by_label("A"), 2);
        assert_eq!(s.node_count_by_label("B"), 2);
    }

    /// ── LA BORNE 64 : CE QUI SE PASSE VRAIMENT ────────────────────────
    ///
    /// `label_bitset` est un `u64` et `label_live_counts` un `[AtomicU64; 64]` :
    /// la base ne peut pas porter plus de 64 etiquettes DISTINCTES. Le store
    /// vivant en porte 38 au dernier audit — il reste 26 places, et rien ne
    /// prevenait avant de les avoir consommees.
    ///
    /// AUCUN TEST NE COUVRAIT CETTE BORNE. Le seul test « 65 » du depot
    /// (`dict.rs`, `too_many_labels_rejected`) verifie la SERIALISATION du
    /// dictionnaire, jamais l'internement : il ne dit rien de ce que fait la
    /// base quand un import presente un 65e label.
    ///
    /// Celui-ci l'etablit : les 64 premieres passent et sont comptees juste ;
    /// la 65e PANIQUE. `LabelRegistry::intern` rend pourtant un `Result`, mais
    /// `create_node` le deplie avec `.expect(...)` — l'erreur ne remonte pas a
    /// l'appelant, elle abat le processus. Ce test ne corrige pas ce choix : il
    /// le rend visible et le fige, pour que le jour ou quelqu'un le change, ce
    /// soit deliberement.
    #[test]
    fn soixante_quatre_etiquettes_passent_et_sont_comptees_juste() {
        let (_td, s) = store();
        for i in 0..64u32 {
            let nom = format!("L{i}");
            let id = s.create_node(&[nom.as_str()]);
            assert!(id.0 > 0, "le noeud {i} doit etre cree");
        }
        assert_eq!(s.node_count(), 64);
        for i in 0..64u32 {
            assert_eq!(
                s.node_count_by_label(&format!("L{i}")),
                1,
                "chaque etiquette porte exactement son noeud"
            );
        }
        // Les 64 bits sont consommes : la base est PLEINE, sans l'avoir dit.
        assert_eq!(s.labels.read().bit_to_name.len(), 64);
    }

    /// La 65e etiquette distincte ne rend pas une erreur : elle PANIQUE.
    ///
    /// Documente le comportement reel de `create_node` (`.expect` sur
    /// `intern_labels_to_bitset`). Un import qui depasse 64 etiquettes abat le
    /// processus au lieu de rendre une erreur que l'appelant pourrait traiter.
    #[test]
    #[should_panic(expected = "label registry overflow")]
    fn la_soixante_cinquieme_etiquette_fait_paniquer_create_node() {
        let (_td, s) = store();
        for i in 0..65u32 {
            s.create_node(&[format!("L{i}").as_str()]);
        }
    }

    /// Meme borne, atteinte par `add_label` — le chemin le plus expose, parce
    /// qu'un `SET n:X` peut introduire une etiquette neuve longtemps apres
    /// l'import, sur une base dont personne ne surveille le compte.
    #[test]
    #[should_panic(expected = "label registry overflow")]
    fn la_soixante_cinquieme_etiquette_fait_paniquer_add_label() {
        let (_td, s) = store();
        let n = s.create_node(&["L0"]);
        for i in 1..64u32 {
            s.create_node(&[format!("L{i}").as_str()]);
        }
        assert_eq!(s.labels.read().bit_to_name.len(), 64);
        s.add_label(n, "LA_GOUTTE_DE_TROP");
    }

    /// ── L'INVARIANT, SOUS SEQUENCE ALEATOIRE ──────────────────────────
    ///
    /// Les deux tests de parite ci-dessus verifient une base MONTEE A LA MAIN :
    /// trois noeuds, quatre aretes, un `add_label`. Ils passent sur toute
    /// implementation qui ne se trompe pas sur ce scenario-la — et c'est
    /// exactement ce qui s'est produit :
    /// `edge_counts_by_type_egale_le_balayage_qu_elle_remplace` est reste vert
    /// pendant qu'une copie de la base `agent` annoncait `IN_MISSION` a 4 660
    /// pour 2 347 aretes reelles.
    ///
    /// Ce test-ci tire une SEQUENCE de mutations et confronte, APRES CHAQUE
    /// PAS, les compteurs au balayage des zones. Il couvre les six mutations
    /// qui deplacent un compteur — creation/suppression de noeud, creation/
    /// suppression d'arete, pose/retrait d'etiquette — plus la REOUVERTURE,
    /// le chemin par lequel une valeur fausse se fige dans l'instantane.
    ///
    /// LE BALAYAGE EST L'ORACLE, JAMAIS L'INVERSE : quand les deux divergent,
    /// c'est le compteur qui ment. Le balayage lit les enregistrements.
    ///
    /// Il reproduit les DEUX exclusions de `rebuild_live_counters_interne` —
    /// tombstone, et creneau nul en source ou en cible. Un oracle qui compte
    /// autrement que le recompte d'ouverture ferait rougir le test sur une
    /// base saine.
    ///
    /// `create_node_in_community` est VOLONTAIREMENT ABSENT de la sequence :
    /// sur ce chemin le balayage n'est pas un oracle, il est AMBIGU. Voir
    /// `un_trou_de_slot_community_est_compte_comme_un_noeud_vivant`, qui
    /// epingle le defaut au lieu de le noyer ici.
    ///
    /// GENERATEUR DETERMINISTE ET INTERNE (xorshift64*) plutot que `rand` ou
    /// `proptest` : une graine ecrite dans le test rejoue exactement la meme
    /// sequence, donc un echec est reproductible sans capturer de graine dans
    /// un message. Les graines sont plusieurs pour que le test ne repose pas
    /// sur la chance d'une seule.
    #[test]
    fn les_compteurs_egalent_le_balayage_sous_mutations_aleatoires() {
        // xorshift64* — quelques lignes, aucune dependance, reproductible.
        struct Graine(u64);
        impl Graine {
            fn suivant(&mut self) -> u64 {
                let mut x = self.0;
                x ^= x >> 12;
                x ^= x << 25;
                x ^= x >> 27;
                self.0 = x;
                x.wrapping_mul(0x2545_F491_4F6C_DD1D)
            }
            fn borne(&mut self, n: u64) -> u64 {
                self.suivant() % n
            }
        }

        /// Le balayage : `(noeuds vivants, compte par bit de label,
        /// aretes vivantes, compte par identifiant de type)`.
        ///
        /// Rend les comptes par BIT et par IDENTIFIANT — pas par nom — pour ne
        /// pas faire dependre l'oracle de la resolution de registre, qui est
        /// justement une des choses qu'on veut pouvoir suspecter.
        fn balayer(
            s: &SubstrateStore,
        ) -> (u64, [u64; 64], u64, std::collections::HashMap<u16, u64>) {
            let mut noeuds = 0u64;
            let mut par_bit = [0u64; 64];
            let borne_n = s.next_node_id.load(Ordering::Acquire);
            for slot in 1..borne_n {
                let Ok(Some(rec)) = s.writer.read_node(slot) else {
                    continue;
                };
                // ── TROU-AWARE (allocation par blocs) ─────────────────────
                // `is_live()` = ALLOCATED && !TOMBSTONED. L'ancien test
                // `!TOMBSTONED` comptait les TROUS (flags == 0, jamais écrits)
                // comme des noeuds vivants : après réouverture la borne vaut 257
                // et le balayage comptait 255 au lieu de 4. Compter ALLOCATED
                // est PLUS strict sur les vivants (un trou n'est jamais un
                // vivant) et PLUS juste sur les trous (légitimes).
                if !rec.is_live() {
                    continue;
                }
                noeuds += 1;
                let mut bits = rec.label_bitset;
                while bits != 0 {
                    let bit = bits.trailing_zeros() as usize;
                    par_bit[bit] += 1;
                    bits &= bits - 1;
                }
            }

            let mut aretes = 0u64;
            let mut par_type: std::collections::HashMap<u16, u64> =
                std::collections::HashMap::new();
            let borne_e = s.next_edge_id.load(Ordering::Acquire);
            for slot in 1..borne_e {
                let Ok(Some(rec)) = s.writer.read_edge(slot) else {
                    continue;
                };
                if rec.flags & crate::record::edge_flags::TOMBSTONED != 0 {
                    continue;
                }
                // Meme exclusion que le recompte d'ouverture : une arete a
                // creneau nul n'est traversable par aucun plan.
                if rec.src == 0 || rec.dst == 0 {
                    continue;
                }
                aretes += 1;
                *par_type.entry(rec.edge_type).or_insert(0) += 1;
            }
            (noeuds, par_bit, aretes, par_type)
        }

        /// Confronte les quatre familles de compteurs au balayage.
        fn confronter(s: &SubstrateStore, etape: &str) {
            let (noeuds, par_bit, aretes, par_type) = balayer(s);

            assert_eq!(
                s.total_live_nodes.load(Ordering::Relaxed),
                noeuds,
                "{etape} : total_live_nodes contre balayage"
            );
            assert_eq!(
                s.total_live_edges.load(Ordering::Relaxed),
                aretes,
                "{etape} : total_live_edges contre balayage"
            );
            for bit in 0..64usize {
                assert_eq!(
                    s.label_live_counts[bit].load(Ordering::Relaxed),
                    par_bit[bit],
                    "{etape} : label_live_counts[{bit}] contre balayage"
                );
            }
            // Les deux sens : un type dont le compteur a derive, ET un type
            // que le compteur ignore alors qu'il porte des aretes vivantes.
            let mut tous: std::collections::HashSet<u16> = par_type.keys().copied().collect();
            for e in s.edge_type_live_counts.iter() {
                tous.insert(*e.key());
            }
            for id in tous {
                let compteur = s
                    .edge_type_live_counts
                    .get(&id)
                    .map(|a| a.load(Ordering::Relaxed))
                    .unwrap_or(0);
                assert_eq!(
                    compteur,
                    par_type.get(&id).copied().unwrap_or(0),
                    "{etape} : compteur du type {id} ({}) contre balayage",
                    s.resolve_edge_type_by_id(id)
                );
            }

            // LA VERIFICATION BON MARCHE, celle qu'on veut pouvoir payer en
            // production : la somme des compteurs par type doit faire le total.
            // Elle ne coute rien — autant d'additions que de types.
            let somme_types: u64 = s
                .edge_type_live_counts
                .iter()
                .map(|e| e.value().load(Ordering::Relaxed))
                .sum();
            assert_eq!(
                somme_types,
                s.total_live_edges.load(Ordering::Relaxed),
                "{etape} : somme des compteurs par type contre edge_count()"
            );

            // Cote noeuds la somme des compteurs de labels ne peut PAS etre
            // comparee a `total_live_nodes` : un noeud multi-etiquette compte
            // dans plusieurs bits. L'invariant juste est un ENCADREMENT —
            // aucun compteur de label ne peut depasser le total.
            for bit in 0..64usize {
                assert!(
                    s.label_live_counts[bit].load(Ordering::Relaxed)
                        <= s.total_live_nodes.load(Ordering::Relaxed),
                    "{etape} : label_live_counts[{bit}] depasse node_count()"
                );
            }
        }

        const ETIQUETTES: [&str; 4] = ["Alpha", "Beta", "Gamma", "Delta"];
        const TYPES: [&str; 3] = ["LIE", "CAUSE", "SUIT"];

        for graine_initiale in [0x5EED_1234_u64, 0xDEAD_BEEF, 0x0BAD_C0DE] {
            let td = tempfile::tempdir().unwrap();
            let chemin = td.path().join("kb");
            let mut g = Graine(graine_initiale);
            let mut noeuds: Vec<NodeId> = Vec::new();
            let mut aretes: Vec<EdgeId> = Vec::new();
            let mut s = SubstrateStore::create(&chemin).unwrap();

            for pas in 0..240u32 {
                let etape = format!("graine {graine_initiale:#x}, pas {pas}");
                match g.borne(100) {
                    // Creation de noeud, 0 a 3 etiquettes : le cas
                    // multi-etiquette doit etre couvert, c'est lui qui separe
                    // la somme des compteurs du total.
                    0..=29 => {
                        let combien = g.borne(4) as usize;
                        let mut lbl: Vec<&str> = Vec::new();
                        for _ in 0..combien {
                            let e = ETIQUETTES[g.borne(4) as usize];
                            if !lbl.contains(&e) {
                                lbl.push(e);
                            }
                        }
                        noeuds.push(s.create_node(&lbl));
                    }
                    30..=54 => {
                        if noeuds.len() >= 2 {
                            let a = noeuds[g.borne(noeuds.len() as u64) as usize];
                            let b = noeuds[g.borne(noeuds.len() as u64) as usize];
                            let t = TYPES[g.borne(3) as usize];
                            aretes.push(s.create_edge(a, b, t));
                        }
                    }
                    55..=66 => {
                        if !noeuds.is_empty() {
                            let i = g.borne(noeuds.len() as u64) as usize;
                            s.delete_node(noeuds[i]);
                        }
                    }
                    67..=78 => {
                        if !aretes.is_empty() {
                            let i = g.borne(aretes.len() as u64) as usize;
                            s.delete_edge(aretes[i]);
                        }
                    }
                    79..=88 => {
                        if !noeuds.is_empty() {
                            let i = g.borne(noeuds.len() as u64) as usize;
                            let e = ETIQUETTES[g.borne(4) as usize];
                            s.add_label(noeuds[i], e);
                        }
                    }
                    89..=96 => {
                        if !noeuds.is_empty() {
                            let i = g.borne(noeuds.len() as u64) as usize;
                            let e = ETIQUETTES[g.borne(4) as usize];
                            s.remove_label(noeuds[i], e);
                        }
                    }
                    // REOUVERTURE : flush, fermeture, ouverture. C'est le pas
                    // qui fait passer les compteurs par l'instantane.
                    _ => {
                        s.flush().expect("flush");
                        drop(s);
                        s = SubstrateStore::open(&chemin).expect("reouverture");
                        confronter(&s, &format!("{etape} (apres reouverture)"));
                        continue;
                    }
                }
                confronter(&s, &etape);
            }

            // Et une reouverture finale, pour que la sequence se termine
            // toujours par le chemin de l'instantane.
            s.flush().expect("flush final");
            drop(s);
            let s = SubstrateStore::open(&chemin).expect("reouverture finale");
            confronter(&s, &format!("graine {graine_initiale:#x}, fin"));
        }
    }

    #[test]
    fn compteurs_et_balayage_s_accordent_apres_reouverture() {
        let td = tempfile::tempdir().unwrap();
        let chemin = td.path().join("kb");
        {
            let s = SubstrateStore::create(&chemin).unwrap();
            let a = s.create_node(&["A"]);
            let b = s.create_node(&["B"]);
            let c = s.create_node(&["A"]);
            s.create_edge(a, b, "LIE");
            s.create_edge(b, c, "LIE");
            s.create_edge(c, a, "AUTRE");
            s.add_label(b, "A");
            let mort = s.create_edge(a, c, "EPHEMERE");
            s.delete_edge(mort);
            s.flush().expect("flush");
        }

        let s = SubstrateStore::open(&chemin).expect("réouverture");

        // Arêtes : compteur global contre balayage.
        let borne = s.next_edge_id.load(Ordering::Acquire);
        let mut vivantes = 0usize;
        let mut par_type: std::collections::HashMap<String, usize> =
            std::collections::HashMap::new();
        for slot in 1..borne {
            let Ok(Some(rec)) = s.writer.read_edge(slot) else {
                continue;
            };
            if rec.flags & crate::record::edge_flags::TOMBSTONED != 0 {
                continue;
            }
            // ── TROU-AWARE (allocation par blocs) ─────────────────────────
            // Après réouverture `borne` est la BORNE (257), pas le nombre
            // d'arêtes : les slots jamais écrits (src/dst == 0) sont des TROUS,
            // pas des arêtes vivantes. Sans cette garde ils seraient comptés
            // (255 au lieu de 3) et `edge_count()` semblerait diverger.
            if rec.src == 0 || rec.dst == 0 {
                continue;
            }
            vivantes += 1;
            *par_type
                .entry(s.resolve_edge_type_by_id(rec.edge_type).to_string())
                .or_insert(0) += 1;
        }
        assert_eq!(
            s.edge_count(),
            vivantes,
            "edge_count() doit s'accorder avec le balayage APRÈS réouverture"
        );
        assert_eq!(
            s.edge_counts_by_type().expect("sait compter"),
            par_type,
            "le comptage par type doit s'accorder avec le balayage"
        );

        // Labels : compteur contre balayage, y compris celui posé par add_label.
        for etiquette in ["A", "B"] {
            assert_eq!(
                s.node_count_by_label(etiquette),
                s.nodes_by_label(etiquette).len(),
                "compteur et balayage doivent s'accorder sur '{etiquette}'"
            );
        }
        assert_eq!(s.node_count_by_label("A"), 3, "a, c, et b via add_label");

        // Et le recomptage ne doit RIEN avoir à corriger.
        let ecarts = s.recount_live_counters().expect("recount");
        assert!(
            ecarts.is_empty(),
            "aucun écart ne doit subsister après réouverture : {ecarts:?}"
        );
    }

    #[test]
    fn recount_ne_rapporte_rien_sur_une_base_saine() {
        // Une réparation qui prétend toujours avoir réparé ne permet plus de
        // savoir si le défaut persiste.
        let (_td, s) = store();
        s.create_node(&["Person"]);
        s.create_node(&["Company"]);
        assert!(s.recount_live_counters().expect("recount").is_empty());
    }

    #[test]
    fn nodes_by_label_filters_correctly() {
        let (_td, s) = store();
        let alice = s.create_node(&["Person"]);
        let bob = s.create_node(&["Person", "Engineer"]);
        let acme = s.create_node(&["Company"]);

        let persons = s.nodes_by_label("Person");
        assert_eq!(persons.len(), 2);
        assert!(persons.contains(&alice) && persons.contains(&bob));
        assert!(!persons.contains(&acme));

        assert_eq!(s.nodes_by_label("Company"), vec![acme]);
        assert_eq!(s.nodes_by_label("Missing"), Vec::<NodeId>::new());
    }

    #[test]
    fn add_label_adds_only_new_labels() {
        let (_td, s) = store();
        let id = s.create_node(&["Person"]);
        assert!(!s.add_label(id, "Person")); // already there
        assert!(s.add_label(id, "Engineer"));
        let n = s.get_node(id).unwrap();
        assert_eq!(n.labels.len(), 2);
        // nodes_by_label now finds it under "Engineer" too.
        assert_eq!(s.nodes_by_label("Engineer"), vec![id]);
    }

    #[test]
    fn remove_label_returns_true_when_present() {
        let (_td, s) = store();
        let id = s.create_node(&["Person", "Engineer"]);
        assert!(s.remove_label(id, "Engineer"));
        let n = s.get_node(id).unwrap();
        assert_eq!(n.labels.len(), 1);
        assert!(!s.remove_label(id, "Engineer"));
    }

    #[test]
    fn find_nodes_by_property_returns_matches() {
        let (_td, s) = store();
        let alice = s.create_node(&["Person"]);
        let bob = s.create_node(&["Person"]);
        s.set_node_property(alice, "dept", Value::from("Eng"));
        s.set_node_property(bob, "dept", Value::from("HR"));

        let eng = s.find_nodes_by_property("dept", &Value::from("Eng"));
        assert_eq!(eng, vec![alice]);
        let hr = s.find_nodes_by_property("dept", &Value::from("HR"));
        assert_eq!(hr, vec![bob]);
    }

    // ── T17b : index de propriété natif substrate ───────────────────────

    /// L'index construit APRÈS les écritures (scan de construction) trouve
    /// les nœuds préexistants, et les résultats sont identiques au scan.
    #[test]
    fn t17b_index_built_after_writes_matches_scan() {
        let (_td, s) = store();
        let a = s.create_node(&["Rec"]);
        let b = s.create_node(&["Rec"]);
        s.set_node_property(a, "id", Value::from("pa_1"));
        s.set_node_property(b, "id", Value::from("pa_2"));

        let scan = s.find_nodes_by_property("id", &Value::from("pa_1"));
        s.create_property_index("id");
        assert!(s.has_property_index("id"));
        let indexed = s.find_nodes_by_property("id", &Value::from("pa_1"));
        assert_eq!(indexed, scan);
        assert_eq!(indexed, vec![a]);
        // Valeur absente : vide, pas d'erreur.
        assert!(
            s.find_nodes_by_property("id", &Value::from("pa_absent"))
                .is_empty()
        );
    }

    /// Écritures APRÈS enregistrement : le hook maintient l'index —
    /// insertion, changement de valeur (l'ancienne sort), suppression.
    #[test]
    fn t17b_index_maintained_by_write_hooks() {
        let (_td, s) = store();
        s.create_property_index("id");
        let a = s.create_node(&["Rec"]);
        s.set_node_property(a, "id", Value::from("v1"));
        assert_eq!(s.find_nodes_by_property("id", &Value::from("v1")), vec![a]);

        // Changement de valeur : v1 ne matche plus, v2 oui.
        s.set_node_property(a, "id", Value::from("v2"));
        assert!(
            s.find_nodes_by_property("id", &Value::from("v1"))
                .is_empty()
        );
        assert_eq!(s.find_nodes_by_property("id", &Value::from("v2")), vec![a]);

        // Suppression de la propriété.
        s.remove_node_property(a, "id");
        assert!(
            s.find_nodes_by_property("id", &Value::from("v2"))
                .is_empty()
        );
    }

    /// Un nœud supprimé disparaît des résultats indexés (tombstone + purge).
    #[test]
    fn t17b_deleted_node_leaves_index_results() {
        let (_td, s) = store();
        s.create_property_index("id");
        let a = s.create_node(&["Rec"]);
        s.set_node_property(a, "id", Value::from("gone"));
        assert_eq!(
            s.find_nodes_by_property("id", &Value::from("gone")),
            vec![a]
        );
        assert!(s.delete_node(a));
        assert!(
            s.find_nodes_by_property("id", &Value::from("gone"))
                .is_empty()
        );
    }

    /// Valeur non projetable (Float64) sur clé indexée : retombe sur le scan
    /// et reste correcte ; drop désenregistre.
    #[test]
    fn t17b_non_indexable_value_falls_back_and_drop_unregisters() {
        let (_td, s) = store();
        s.create_property_index("score");
        let a = s.create_node(&["Rec"]);
        s.set_node_property(a, "score", Value::from(1.5f64));
        assert_eq!(
            s.find_nodes_by_property("score", &Value::from(1.5f64)),
            vec![a]
        );
        assert!(s.drop_property_index("score"));
        assert!(!s.has_property_index("score"));
        assert!(!s.drop_property_index("score"));
    }

    /// ── EXISTENCE PAR LA SÉRIE DE PROPRIÉTÉ ──────────────────────────────
    ///
    /// Le contrat tient en trois lignes : une propriété NON déclarée rend
    /// `None` (on balaie), une propriété déclarée rend EXACTEMENT ses
    /// porteurs, et un porteur qui meurt ou qui perd la propriété sort de la
    /// liste — l'index n'est jamais cru sur parole.
    #[test]
    fn existence_par_serie_de_propriete_est_exacte_et_se_tait_sans_declaration() {
        let (_td, s) = store();
        let a = s.create_node(&["Rec"]);
        let b = s.create_node(&["Rec"]);
        let c = s.create_node(&["Rec"]);
        s.set_node_property(a, "id", Value::from("pa_1"));
        s.set_node_property(b, "id", Value::from("pa_2"));
        // `c` porte une AUTRE propriété : il ne doit jamais sortir de `id`.
        s.set_node_property(c, "rang", Value::from(1_i64));

        // Non déclarée : « je ne sais pas répondre sans balayer ».
        assert_eq!(s.find_nodes_with_property("id"), None);

        s.create_property_index("id");
        let porteurs = s
            .find_nodes_with_property("id")
            .expect("propriete declaree : la serie doit repondre");
        assert_eq!(porteurs, vec![a, b], "les seuls porteurs de `id`, tries");

        // Déclarée mais portée par PERSONNE : série vide = ambiguïté, donc
        // `None` — le balayage reste, il rend la même chose.
        s.create_property_index("personne_ne_la_porte");
        assert_eq!(s.find_nodes_with_property("personne_ne_la_porte"), None);

        // Un porteur de plus, APRÈS la construction : il entre.
        let d = s.create_node(&["Rec"]);
        s.set_node_property(d, "id", Value::from("pa_3"));
        let porteurs = s.find_nodes_with_property("id").expect("serie toujours la");
        assert_eq!(porteurs, vec![a, b, d], "l'ecriture de session doit entrer");

        // Le noeud DÉTACHÉ sort : la revérification de vivacité le coupe.
        s.delete_node(b);
        let porteurs = s.find_nodes_with_property("id").expect("serie toujours la");
        assert_eq!(porteurs, vec![a, d], "un noeud mort reste dans la liste");
    }

    /// `find_nodes_by_properties` multi-conditions passe par l'index quand
