    #[test]
    fn typed_degree_stays_healthy_across_live_writes_after_heal() {
        // (2026-09-05) Après un heal (test ci-dessus), les écritures vives
        // suivantes maintiennent la colonne — pas de re-déclenchement du
        // heal, pas de perte de fiabilité.
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb-vif");
        let a_id = {
            let s = SubstrateStore::create(&path).unwrap();
            let a = s.create_node(&["File"]);
            let b = s.create_node(&["File"]);
            let _ = s.create_edge(a, b, "TOUCHES");
            s.flush().unwrap();
            a
        };
        // Péremption du sidecar TOUCHES puis réouverture en écriture → heal.
        let col_path = path.join(crate::typed_degree::filename_for_type("TOUCHES"));
        let bytes = std::fs::read(&col_path).unwrap();
        let n_slots = u32::from_le_bytes(bytes[8..12].try_into().unwrap()) as usize;
        let payload_bytes = n_slots * crate::degree_column::DEGREE_RECORD_SIZE;
        let mut out = Vec::with_capacity(bytes.len());
        out.extend_from_slice(&bytes[..64]);
        out.resize(64 + payload_bytes, 0u8);
        let crc = {
            let mut h = crc32fast::Hasher::new();
            h.update(&out[64..]);
            h.finalize()
        };
        out[16..20].copy_from_slice(&crc.to_le_bytes());
        std::fs::write(&col_path, &out).unwrap();

        let s = SubstrateStore::open(&path).unwrap();
        // Le heal se déclenche à la première utilisation typed…
        assert_eq!(s.out_degree_by_type(a_id, "TOUCHES"), 1);
        // …la colonne reste fiable et suit les nouvelles écritures.
        assert!(GraphStore::typed_degree_reliable(&s, "TOUCHES"));
        let c = s.create_node(&["File"]);
        let _ = s.create_edge(a_id, c, "TOUCHES");
        assert_eq!(s.out_degree_by_type(a_id, "TOUCHES"), 2);
        assert!(GraphStore::typed_degree_reliable(&s, "TOUCHES"));
        // Et la fiabilité survit à la réouverture (colonne persistera
        // correcte au prochain flush).
        s.flush().unwrap();
        drop(s);
        let s2 = SubstrateStore::open(&path).unwrap();
        assert_eq!(s2.out_degree_by_type(a_id, "TOUCHES"), 2);
        assert!(GraphStore::typed_degree_reliable(&s2, "TOUCHES"));
    }

    /// (2026-09-05) CONCURRENCE — writers multi-threads sur un store guéri :
    /// l'auto-guérison se déclenche à la première utilisation typed (verrou
    /// de santé tenu jusqu'à la fin du heal), donc AUCUN incrément ne peut
    /// être perdu entre le zero et le rescan ; après le heal, les colonnes
    /// suivent exactement les arêtes créées par tous les threads.
    #[test]
    fn typed_degree_heal_concurrent_writers_no_lost_increment() {
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb-conc");
        // Store de base avec UNE arête TOUCHES, puis flush + fermeture.
        let seed = {
            let s = SubstrateStore::create(&path).unwrap();
            let a = s.create_node(&["N"]);
            let b = s.create_node(&["N"]);
            let _ = s.create_edge(a, b, "TOUCHES");
            s.flush().unwrap();
            a
        };
        // Péremption du sidecar TOUCHES (payload zéro, CRC recalculé valide).
        let col_path = path.join(crate::typed_degree::filename_for_type("TOUCHES"));
        let bytes = std::fs::read(&col_path).unwrap();
        let n_slots = u32::from_le_bytes(bytes[8..12].try_into().unwrap()) as usize;
        let payload_bytes = n_slots * crate::degree_column::DEGREE_RECORD_SIZE;
        let mut out = Vec::with_capacity(bytes.len());
        out.extend_from_slice(&bytes[..64]);
        out.resize(64 + payload_bytes, 0u8);
        let crc = {
            let mut h = crc32fast::Hasher::new();
            h.update(&out[64..]);
            h.finalize()
        };
        out[16..20].copy_from_slice(&crc.to_le_bytes());
        std::fs::write(&col_path, &out).unwrap();

        let s = Arc::new(SubstrateStore::open(&path).unwrap());
        const THREADS: usize = 4;
        const PAR_THREAD: usize = 60;
        let mut handles = Vec::new();
        for t in 0..THREADS {
            let store = Arc::clone(&s);
            handles.push(std::thread::spawn(move || {
                // Chaque thread écrit depuis un nœud source distinct. Le
                // premier `create_edge` déclenche hydratation + heal (une
                // fois, sérialisé par le verrou de santé) ; les suivants
                // passent le fast-path.
                let src = store.create_node(&["N"]);
                for _ in 0..PAR_THREAD {
                    let dst = store.create_node(&["N"]);
                    let _ = store.create_edge(src, dst, "TOUCHES");
                }
                src
            }));
        }
        let sources: Vec<_> = handles
            .into_iter()
            .map(|h| h.join().expect("thread writer"))
            .collect();
        // La colonne TOUCHES est fiable et EXACTE pour chaque source.
        assert!(GraphStore::typed_degree_reliable(&*s, "TOUCHES"));
        for src in sources {
            assert_eq!(
                s.out_degree_by_type(src, "TOUCHES"),
                PAR_THREAD as u32,
                "aucun incrément perdu par le heal concurrent"
            );
        }
        // Le nœud seed initial garde son arête (le heal l'a rescannée).
        assert_eq!(s.out_degree_by_type(seed, "TOUCHES"), 1);
        s.flush().unwrap();
    }

    /// (2026-09-05) `edge_endpoints_by_id` — accesseur public des extrémités
    /// d'une arête vivante (utilisé par `search_surprise`).
    #[test]
    fn edge_endpoints_by_id_round_trip() {
        let (_td, s) = store();
        let a = s.create_node(&["A"]);
        let b = s.create_node(&["B"]);
        let e = s.create_edge(a, b, "R");
        let eps = s.edge_endpoints_by_id(e).expect("extrémités");
        assert_eq!(eps, (a, b), "extrémités (src, dst)");
        // Id hors registre → None.
        assert!(
            s.edge_endpoints_by_id(obrain_common::types::EdgeId(u64::MAX))
                .is_none()
        );
        assert!(
            s.edge_endpoints_by_id(obrain_common::types::EdgeId(0))
                .is_none()
        );
        // Après suppression (tombstone) → None.
        s.delete_edge(e);
        assert!(
            s.edge_endpoints_by_id(e).is_none(),
            "arête tombstonée → None"
        );
    }

    /// (2026-09-05) `for_each_live_edge` — un seul verrou, tombstone filtré.
    #[test]
    fn for_each_live_edge_parcourt_les_vivantes() {
        let (_td, s) = store();
        let a = s.create_node(&["A"]);
        let b = s.create_node(&["B"]);
        let c = s.create_node(&["C"]);
        let e1 = s.create_edge(a, b, "R");
        let _e2 = s.create_edge(a, c, "R");
        s.delete_edge(e1); // tombstone
        let mut vues = 0usize;
        s.for_each_live_edge(|_slot, _rec| vues += 1).unwrap();
        assert_eq!(vues, 1, "une seule arête vivante");
    }

