    /// Une suppression post-snapshot ne doit pas etre RESSUSCITEE par le
    /// snapshot au reopen — PropRemoveInline la rejoue par-dessus.
    /// Corps du scenario — SANS le drapeau : les deux enveloppes
    /// ci-dessous l eprouvent sous chacun des deux regimes.
    fn scenario_a_delete_after_snapshot_is_not_resurrected_on_reopen() {
        let td = tempfile::tempdir().unwrap();
        let path = td.path().join("kb");
        let node_id;
        {
            let s = SubstrateStore::create(&path).unwrap();
            let a = s.create_node(&["Doc"]);
            node_id = a;
            s.set_node_property(a, "secret", Value::String("x".into()));
            s.flush().unwrap(); // snapshot porte secret
            let _ = s.remove_node_property(a, "secret"); // post-snapshot
            s.fsync_wal().unwrap();
            // Un vrai kill rend les verrous : le noyau ferme les descripteurs.
            s.deverrouiller_pour_simuler_un_kill();
            std::mem::forget(s);
        }
        let s2 = SubstrateStore::open(&path).unwrap();
        assert_eq!(
            s2.get_node_property(node_id, &PropertyKey::new("secret")),
            None,
            "une propriete supprimee apres le snapshot ne doit pas ressusciter"
        );
    }

